// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":803,"question":"إنني وصيٌّ على أيتامٍ، ولهم مبلغٌ من المال، وأشغله بالتِّجارة، وفي بعض الأحيان أحتاج إلى بعضه، وأقترض منه قرضةً حسنةً، فهل يجوز لي أن آخذ منه شيئًا؟","title":"هل يجوز الاقتراض من أموال اليتامى؟","answer":"الجواب: بسم الله، والصلاة والسلام على رسول الله، الأحوط لك يا أخي عدم الأخذ؛ لأنَّ الإنسان قد يتساهل فيما تحت يده من جهة الأيتام، فينبغي لك أن تقترض من غيرهم، وأن تجتهد في تنمية مالهم والإصلاح لهم، لكن إذا كنتَ محتاجًا مثلما قال الله جلَّ وعلا: وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ [النساء:6]، فإذا كنتَ محتاجًا فلك الأكل بالمعروف، والأحوط لك أن تتَّفق مع الحاكم الشَّرعي –القاضي- على شيءٍ معلومٍ عن تعبِك، وإلا فدع ذلك؛ لأنَّك إذا اقترضتَ من أموالهم قد يتأخّر عندك، ويتعطل عندك، ليس لك مَن يُطالبه، فالأحوط لك ألا تأخذ من أموالهم قرضًا، أما عن تعبك فلا بأس أن تأخذ عن تعبك شيئًا بواسطة المحكمة، تتفق مع المحكمة على شيءٍ.","link":"https://binbaz.org.sa/fatwas/20780/هل-يجوز-الاقتراض-من-اموال-اليتامى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0611حكم الاقتراض من أموال اليتامى ؟ ابن باز فتاوى المحاضرات.mp3","categories":["السلف والقرض"]},{"id":1191,"question":"هل يجوز أن أشتري من فلاحٍ بُرًّا، وأُعطيه كيسًا مثل الذي أخذتُ منه عند الحصاد، أو أقول له: سلفة، أو كيس بكيسين؟","title":"حكم شراء بُرّ ثم ردِّه بمثله عند الحصاد","answer":"الجواب:\nهذا فيه تفصيل: أما السلف: أن تأخذ منه كيسًا فيه مئة صاع، أو مئتا صاعٍ، أربعون كيلو، ثلاثون كيلو، على سبيل السلف والقرض؛ فلا بأس، سواء تمرًا أو أرزًا أو غيره، على سبيل القرض والسلف. أما البيع: فلا تشترِ شيئًا من الحبوب بحبوبٍ أخرى مُؤجَّلة، لا بالمثل، ولا بالأكثر، تقول: أعطني مثلًا كيسًا فيه أربعون كيلو من التمر أو من الأرز بستين كيلو إلى أجلٍ، هذا ربا، ما يجوز هذا، ولو نقدًا أيضًا، ما تأخذ أربعين كيلو طيبة من التمر بستين كيلو رديئة من التمر، هذا ربا، ولو في الحال، لا بدّ أن يكون مثلًا بمثلٍ، صاعًا بصاعٍ، كيلو بكيلو، ما يزيد هذا على هذا من التمر، وهكذا من الأرز، وهكذا من الحنطة، أما إذا كان مختلفًا: فإن أخذتَ مثلًا أربعين كيلو من الحنطة بخمسين كيلو من الشعير، أو أربعين كيلو من الحنطة بثلاثين كيلو من الأرز مختلفة، يدًا بيدٍ؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/21241/حكم-شراء-بر-ثم-رده-بمثله-عند-الحصاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1153هل يجوز أن أشتري من فلاح بر وأعطيه كيس مثل الذي أخذته منه عند الحصاد؟ ابن باز.mp3","categories":["الربا والصرف","السلف والقرض"]},{"id":1463,"question":"مَن قال بأن الدَّيْنَ مكروهٌ إلا لحاجةٍ؟","title":"هل الدَّين (القرض) مكروه؟","answer":"الجواب:\nوجيهٌ، فالدَّيْن الذي ما له حاجة تركه أوْلى، لا يستدين إلا لحاجةٍ، فالدَّيْنُ خطرٌ؛ فقد يُبْتَلَى ولا يتيسَّر له قضاؤه.\nس: لكن ما ورد عن بعض الصحابة أنهم كانوا يستدينون لسماعهم بعض الأحاديث التي وردت عن النبي ﷺ في فضل التَّداين والقضاء، فهل هي صحيحة؟\nج: ما أتذكر منها شيئًا، لكن إذا قضى حاجة أخيه وسلَّفه وأعطاه فهو مأجورٌ، وفي الحديث الصحيح: مَن نفَّس عن مؤمنٍ كربةً من كُرَب الدنيا نفَّس اللهُ عنه كُربةً من كُرَبِ يوم القيامة، والدَّيْن لا بأس به إذا أخذه للبيع والشراء وهو يريد الوفاء، فلا بأس، يقول النبيُّ ﷺ: مَن أخذ أموالَ الناس يريد أداءها أدَّى الله عنها، ما فيها شيء، لكن إذا تركها خوفًا من مَعَرَّتِها ما في بأس، فالأمر واسع.\nس: ما ورد عن ميمونة أم المؤمنين رضي الله عنها شيءٌ في ذلك؟\nج: ما أتذكر شيئًا.","link":"https://binbaz.org.sa/fatwas/21560/هل-الدين-القرض-مكروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الدَّين مكروه.mp3","categories":["السلف والقرض"]},{"id":1466,"question":"الكافر إذا أسلم هل يبقى عليه الدَّيْن؟","title":"هل يسقط الدَّيْن على الكافر إذا أسلم؟","answer":"الجواب:\nنعم، ديون الناس تبقى، فيُعطيهم إذا كان يعرفهم، فالإسلام لا يُسقط الدَّيْنَ، حقوق الناس يُعطيهم إيَّاها، الإسلام يسقط حقَّ الله، فجميع ما سلف من الشرور يعفو الله عنها، لكن إذا كان عنده أموال للناس أمانة أو حقوق أو دَيْن فلا بدّ أن يُؤدِّيها.\nس: إذا كانوا بعيدين؟\nج: يُرسلها لهم بالطرق التي يرجو وصولها.\nس: وإذا كانوا كفَّارًا حربيين، كان قد استدان منهم قبل أن يُسلم؟\nج: ولو، الظاهر أنه يُعطيهم حقوقهم.","link":"https://binbaz.org.sa/fatwas/21563/هل-يسقط-الدين-على-الكافر-اذا-اسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يسقط الدَّين على الكافر إذا أسلم.mp3","categories":["السلف والقرض"]},{"id":1689,"question":"رجلٌ عليه دَيْنٌ فهل له أن يُسافر إلى الخارج لتعلم اللغة الأجنبية من أجل الدَّعوة إلى الله، أو يُقال: هذا بالمنع أولى من منع مَن عليه دَيْنٌ من الحج؟","title":"حكم سفر مَن عليه دَيْن للحج والدعوة","answer":"الجواب:\nإذا كان هذا السفرُ يضُرُّ الدَّائنين فلا يُسافر، يبدأ بالدَّين، أمَّا إذا لم يكن يضُرُّ الدَّائنين: ما عنده عمل، ولا وجد عملًا، ولعله يتعلَّم هذا الشيء حتى يُوظَّف، ويُوفي دَيْنَه، وينفع المسلمين، أمَّا إذا كان عنده عمل ويستطيع قضاء الدَّيْن، ويسدّ ما عليه؛ فلا يُسافر.\nس: لكن منع مَن عليه دَيْنٌ من الحج هل لأجل الخوف ..؟\nج: يُمْنَع من الحج إذا كان سفرُه يضُرُّ الدَّائنين، أما إذا لم يكن يضُرُّ الدَّائنين - كأن يُسافر مع أُناسٍ والنفقة على غيره - فلا يُمنع؛ لأنَّ حجَّه لا يضُرُّهم.","link":"https://binbaz.org.sa/fatwas/21795/حكم-سفر-من-عليه-دين-للحج-والدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم سفر من عليه دين للدعوة أو للدراسة أو للحج.mp3","categories":["السلف والقرض"]},{"id":2012,"question":"رجل أقرض رجلًا مبلغًا إلى أجل ثم بعد ذلك عند إعادته للمال زاد عليه قليلًا مبلغ خمسمائة ريال؟","title":"حكم الزيادة في رَدِّ القرض دون شرط","answer":"الجواب:\nمن دون شرط يعني؟\nس: من دون شرط.\nالشيخ: ما في بأس؛ إن خيار الناس أحسنهم قضاء، كان النبي ﷺ يقرض الثلاثين ويردها إلى الستين، إذا كان من غير شرط فلا بأس، إن من خيار الناس أحسنهم قضاء.\nس: ما يدخل تحت: أي قرض جر منفعة فهو ربا؟\nالشيخ: لا، ذاك المتفق عليه في الشرط.","link":"https://binbaz.org.sa/fatwas/22128/حكم-الزيادة-في-رد-القرض-دون-شرط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الزيادة في القرض من دون شرط.mp3","categories":["السلف والقرض"]},{"id":2737,"question":"ما يكون الدينُ قرينَ الشرك؟","title":"هل يكون الدَّين قرين الشرك؟","answer":"الجواب: لا، الدين حق آدمي معلّق، إن لم يقضه لصاحبه قضي لصاحبه: فإن كان المدين مفرطًا فهو على خطر، وإن كان ما فرط فالله يقضي عنه ، إن كان معذورًا فالله يقضي عنه، يقول ﷺ: من أخذ أموال الناس يريد أداءها أدّى الله عنه، ومن أخذها يريد إتلافها أتلفه الله رواه البخاري في الصحيح.","link":"https://binbaz.org.sa/fatwas/22885/هل-يكون-الدين-قرين-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون الدَّين قرين الشرك.mp3","categories":["السلف والقرض"]},{"id":2740,"question":"الدين مكروه إلا مِن حاجة أو مُحَرَّم؟","title":"هل الدَّين مُحَرَّم أو مكروه؟","answer":"الجواب: لا، ما هو محرم، إن استدان لمصلحة شرعية ما في بأس .\nس:الكراهة إلا لحاجة؟\nالشيخ: الاستدانة إنما تكون للحاجة، ما تكون للعبث.\nس: هناك من المستدينين من توسعوا؟\nالشيخ: الأصل الاستدانة للحاجة؛ لأنه ما هو بصدقة، مالٌ في مقابل، يُرَدّ كالقرض.\nس: الاستدانة للزواج؟\nالشيخ: ما في بأس، حَرِيٌّ بالوفاء أن الله يُوفِي عنه.\nس: هل ورد فيها حديث؟\nالشيخ: الله مع المدين حتى يُوفِي.\nس: مَن عليه دَيْن هل يمنع من الصدقة؟\nالشيخ: الواجب عليه يبدأ بالدين إلا... شيء خفيف أو الصدقة الخفيفة؛ ما في بأس. لكن الصدقة التي تضر الدين لا، يبدأ بالدين، الواجب مُقَدّم على التطوع.","link":"https://binbaz.org.sa/fatwas/22888/هل-الدين-محرم-او-مكروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الدَّين مكروه أو محرم.mp3","categories":["السلف والقرض"]},{"id":2803,"question":"بعض الناس إذا سلف أحدًا ولم يقم بالتسديد يقول له: اعتبرها زكاة علي؟","title":"حكم مدين يطلب من دائنه اعتبارها زكاة","answer":"الجواب: لا، الدين ما يصير زكاة، لا بدّ يُنْظِره؛ إذا أيسر يُوفِيه، وإما يعفيه من غير الزكاة، صدقة لا بأس، أما الزكاة ما تكون إعفاء من الدين، الزكاة إعطاء؛ يعطيه ما عنده، أما الدين يُنْظَر ويُمْهَل، لكن إذا سامحه تطوعًا طلبًا لمرضاة الله من غير الزكاة فهو مشكور مأجور.","link":"https://binbaz.org.sa/fatwas/22951/حكم-مدين-يطلب-من-داىنه-اعتبارها-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مدين لم يقم بالتسديد فيقول للدائن اعتبرها زكاة علي.mp3","categories":["السلف والقرض"]},{"id":2810,"question":"إذا كان المُعْسِر مُفَرِّطًا يدخل في أعمال تجارية ويكلّف نفسه فوق الطاقة؟","title":"حكم المُعْسر المُفَرِّط الذي يتحمل فوق طاقته","answer":"الجواب: الله يتولى حسابه، إذا كان معسرًا يُنْظَر، أما مع كونه فرّط أو ما فرّط هذا بينه وبين ربه؛ فإن عُرِف أنه فرّط استحق العقوبة، على كل حال الواجب عليه أن يتقي الله.","link":"https://binbaz.org.sa/fatwas/22959/حكم-المعسر-المفرط-الذي-يتحمل-فوق-طاقته","audio":"undefined","categories":["السلف والقرض"]},{"id":3045,"question":"هل يجب كتابة الدَّيْن؟","title":"ما حكم كتابة الدَّيْن؟","answer":"الجواب: الله أمر بذلك، وجاء في الحديث ما يؤيد ذلك، فينبغي كتابة الدين؛ لأن كل واحد قد يَنسى.","link":"https://binbaz.org.sa/fatwas/23205/ما-حكم-كتابة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتابة الدَّين.mp3","categories":["السلف والقرض"]},{"id":3224,"question":"حكم الجمعيات التي يفعلها بعض الناس، جزء من الراتب كل شهر يُدفع ويأخذها واحدٌ؟","title":"حكم الجمعيات المالية التي تُقام بين الموظفين","answer":"الجواب: إذا اتفقوا على ذلك من دون شرط ما في بأس، إذا اتفقوا على ذلك تبرعًا منهم فلا بأس فيما بينهم، كل واحد يقضي القرض الذي عليه، أما بشرط لا، شرط أن تقرضني ينبغي ترك هذا، أما إذا كان إن أقرضه فلا بأس بدون شرط؛ ما في بأس.\nس: تكون بشرط يا شيخ؟\nج: بشرط ينبغي تركه.","link":"https://binbaz.org.sa/fatwas/23387/حكم-الجمعيات-المالية-التي-تقام-بين-الموظفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الجمعيات التي تقام بين الموظفين.mp3","categories":["السلف والقرض"]},{"id":3665,"question":"التدين (الاقتراض) للزوجة الثانية والثالثة؟","title":"حكم من يستدين ليتزوج الثانية والثالثة","answer":"الجواب: ما في بأس، إذا كان له وفاء لا بأس، يتدين ويتزوج إذا كان له وفاء؛ يتسبب ويبيع ويشتري أو يؤجر نفسه؛ لا بأس.\nس: ويأخذ من الزكاة؟\nالشيخ: إذا احتاج لا بأس، إذا كان غارمًا أو ليس بيده شيء يُعطى من الزكاة ما يتزوج به.","link":"https://binbaz.org.sa/fatwas/23853/حكم-من-يستدين-ليتزوج-الثانية-والثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التدين ليتزوج الثانية والثالثة.mp3","categories":["السلف والقرض","الربا والصرف"]},{"id":4185,"question":"لو مثلًا أسلف في سيارة جديدة معروضة، ما هي مستعملة؟","title":"كيف يتم ضبط السلف في الشيء المعلوم؟","answer":"الجواب: إذا انضبطت بالصفات؛ فلا بأس.  إذا قال: أشتري منك سيارة موديل كذا صفة كذا، شيء مضبوط، إلى أجل معلوم ونقده الثمن؛ فلا بأس، سيارة أو سلاح معلوم أو ملابس معلومة.","link":"https://binbaz.org.sa/fatwas/24442/كيف-يتم-ضبط-السلف-في-الشيء-المعلوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السلف في الشيء المعلوم.mp3","categories":["السلف والقرض"]},{"id":4186,"question":"لو أخذ منه خمسة آصع وردها ستة بدون شرط؟","title":"ما حكم رد القرض مع زيادة فوق قيمته؟","answer":"الجواب: يعني إحسان، ما في بأس؛ حتى يعطيه مائة ما في بأس، جزاه الله خيرًا، حتى الدراهم، حتى الذهب والفضة، لو أعطاه، تسلّف منه، خمسة جنيهات وأعطاه ستًّا، أو تسلف منه مائة ريال وأعطاه مائتين؛ ما في بأس، لكن من دون شرط ولا تواطؤ.","link":"https://binbaz.org.sa/fatwas/24443/ما-حكم-رد-القرض-مع-زيادة-فوق-قيمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا أخذ خمسة آصع وردها ستة بدون شرط.mp3","categories":["السلف والقرض"]},{"id":4888,"question":"الذي كان كافرًا ثم أسلم وكان تاجرًا وترك الديون ما حكمه؟","title":"حكم من كان كافرًا ثم أسلم وعليه ديون للناس؟","answer":"إذا أسلم يسدد الدين الذي عليه، يلزم، يسدد الدين إذا طالبه غرماؤه، وإذا سامحوه جزاهم الله خيرًا.\nس: حتى إذا كانت الديون في الخمر؟\nج: لا، لا، ديون ثابتة شرعية.","link":"https://binbaz.org.sa/fatwas/25400/حكم-من-كان-كافرا-ثم-اسلم-وعليه-ديون-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تسقط الديون بالإسلام.mp3","categories":["السلف والقرض"]},{"id":4900,"question":"يذهب الإنسان إلى المؤسسة المالية وتقرضه مثلًا ألف جنيه، وتقول له: الألف جنيه هذه أنا أعطيك سندًا فيها بقيمتها بالدولار، فإذا جئت أنت بعدما تنزل قيمه الجنيه تزدنا إياها بالدولار؟","title":"هل يجوز لمن اقترض جنيهات أن يردها بالدولار؟","answer":"إذا استلف شيئًا؛ له ما استلف، يسلمه له في وقته وإلا قيمته، مثل ما قال النبي ﷺ: لا بأس أن تأخذها بسعر يومها ما لم تفترقا وبينكم شيء، فإذا استلف ليرة لبنانية أو ليرة سورية عند الوفاء يعطيها نفس العملة التي لا زالت دارجة أو قيمتها وقت القبض، ما هو وقت الأخذ منه والشراء، لا، يسلمه قيمتها وقت الوفاء، فإذا صار الوفاء بينهم يسلم له في محرم، فإذا جاء محرم يعطيه الليرة أو قيمتها بالدولار أو بغير الدولار، لا بأس أن تأخذها بسعر يومها، قال: يا رسول الله، نبيع بالدنانير ونأخذ بالدراهم، ونبيع بالدراهم ونأخذ الدنانير، قال ﷺ: لا بأس أن تأخذها بسعر يومها ما لم تفترقا وبينكم شيء.","link":"https://binbaz.org.sa/fatwas/25415/هل-يجوز-لمن-اقترض-جنيهات-ان-يردها-بالدولار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز لمن اقترض جنيها أن يرده دولار.mp3","categories":["السلف والقرض"]},{"id":4901,"question":"بعض البنوك لا تأخذ فائدة، لكن تجعل هناك شرطًا جزائيًّا إذا تأخر المقترض عن الوفاء؟","title":"ما حكم الشرط الجزائي في قروض البنوك؟","answer":"هذا ربا الجاهلية، يقول: إذا حل الأجل ولم تقضني تُربي. هذا ربا الجاهلية: إما أن تُربي وإما أن تَقضي.","link":"https://binbaz.org.sa/fatwas/25416/ما-حكم-الشرط-الجزاىي-في-قروض-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الشرط الجزائي في البنوك عند القرض.mp3","categories":["السلف والقرض"]},{"id":5163,"question":"لقد اطلعنا على فتوى هيئة كبار العلماء الصَّادرة بجواز ما يُسمَّى بالجمعيات التعاونية، و ما الحكم إذا تُوفي أحدُ أعضائها وانتقل من عمله؟ وهل على آخر واحد أو مَن قبله زكاة إذا استلمها؛ لأنه طاف عليها قرابة السنة؟","title":"ما الحكم إذا توفي أحد أعضاء الجمعيات التعاونية؟","answer":"الجواب: هذا قرضٌ، فإذا مات يُعطى حقَّه، إذا مات وعليه قرضٌ يؤخذ منه، وإذا مات وله شيءٌ يُعطى إياه من القروض وما يعتاده الناس، مثل: أن يتسلف عشرين ألفًا، عشرة آلاف في كلِّ شهرٍ، وكذا إذا مات وله شيءٌ يُعطى إيَّاه، وإن كان عليه شيءٌ يُؤخذ من تركته مثل الديون الأخرى.","link":"https://binbaz.org.sa/fatwas/30088/ما-الحكم-اذا-توفي-احد-اعضاء-الجمعيات-التعاونية","audio":"https://files.zadapps.info/binbaz.org.sa/fatwa 112.mp3","categories":["السلف والقرض"]},{"id":5175,"question":"ما حكم الجمعيات التي بين المُوظفين؟","title":"ما حكم الجمعيات التي تدور بين المُوظفين؟","answer":"الجواب: الجمعيات التي تتعارف بين الناس الآن بالقرض، فيجتمعون، وكل واحدٍ يقترض كذا وكذا كل شهر: هذا ألف، وهذا ألف، يأخذ هذا عشرين ألفًا، والآخر يأخذ الشهر الآخر، والثاني الشهر الثاني، وهكذا؛ هذه كانت فيها بعض الشُّبَه والاختلاف وخُشي أن تكون من قرضٍ جرَّ منفعة، ثم درسنا هذا في مجلس هيئة كبار العلماء وصدر القرار بالأكثرية أنه لا حرج في ذلك إن شاء الله؛ لأنه قرضٌ لا يجر منفعة، بل كل واحدٍ يأخذ مثل أخيه، سواء بسواء، لا زيادة.","link":"https://binbaz.org.sa/fatwas/30106/ما-حكم-الجمعيات-التي-تدور-بين-الموظفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 133.mp3","categories":["السلف والقرض"]},{"id":5289,"question":"إنسان عليه دين بالعملة المصرية فهل يجوز أداؤها بعملة غير مصرية؟","title":"هل يجوز قضاء الدَّين بعملة مختلفة؟","answer":"الجواب: نعم إذا اتفقوا على ذلك فلا بأس، سئل النبي ﷺ: يا رسول الله نبيع بالدراهم ونأخذ الدنانير ونبيع بالدنانير ونأخذ الدراهم قال: لا بأس أن تأخذها بسعر يومها حتى تفترقا وبينكما شيء فإذا باع بالعملة المصرية ثم أخذ مقابلها بالعملة السعودية أو غيرها يدًا بيد بالحال في المجلس فلا بأس قبضًا، يعني يقابضان في المجلس.[1]","link":"https://binbaz.org.sa/fatwas/30934/هل-يجوز-قضاء-الدين-بعملة-مختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 010.mp3","categories":["السلف والقرض"]},{"id":6557,"question":"أعمل بأحد البنوك، وأخذت قرضًا لتسديد السكن، حيث إن البنك يأخذ عمولة على هذا القرض، فما حكم الدين؟ وأيضًا رواتبنا من هذا البنك تتحصل من العمولة التي يحصلها البنك على المبالغ المقروضة لبعض العملاء، فما حكم الدين، وما حكم الراتب من هذا البنك؟","title":"حكم الاقتراض من البنك وأخذ الراتب منه","answer":"الجواب: أما الدين فلا يجوز، عليك أن ترد الأصل فقط، وليس لهم حق في الزيادة، وأما كون القرض تخصم من هذا البنك فالإثم على من أخذ الربا، أنت تأخذ راتبك، والبنك فيه الطيب والرديء، البنك فيه أشياء بحق، وأشياء بغير حق، ولست تعلم أن هذا من الربا، أو من غير الربا، أما كونك تعامل بالربا لا يجوز لك هذا، وما أخذته من الفائدة مائة فيها عشرة، أو فيها خمسة عشر ليس لك ذلك، هذا لا يجوز لك، وإذا كانت باقية عندك ليس لك تسليمها لهم.  السؤال: العمل في البنك؟ الجواب: لا يجوز عمله في البنك أيضًا؛ لأنه يعين على الإثم، والعدوان.","link":"https://binbaz.org.sa/fatwas/2395/حكم-الاقتراض-من-البنك-واخذ-الراتب-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_924.mp3","categories":["الربا والصرف","السلف والقرض"]},{"id":6562,"question":"اقترضت من شخص مبلغًا من المال، ثم توفي قبل أن أقوم بتسديد هذا المبلغ، ولم أجد له ورثة، فكيف أتصرف في هذا المال؟","title":"حكم المال الذي توفي صاحبه وليس له ورثة","answer":"الجواب: إذا كان عليك دين لإنسان، وقد توفي، ولا تعلم له ورثه؛ تتصدق به عنه، تعطيه بعض الفقراء بالنية عن صاحبه، فينفعه ذلك في الدنيا والآخرة، ينفعه في موته، وينفعك أيضًا في براءة الذمة، هذا إذا كنت لا تعرف له ورثة، ولكن لا تعجل حتى تسأل عنه أهل المعرفة بذلك؛ لعلك تجد ورثة له.  فإذا مضت مدة طويلة، ولم تعرف له وارثًا، فتصدق به عنه، أو أعطه بيت المال، والصدقة عنه أحسن في هذا الباب، تصدق عنه للفقراء المعروفين بالنية عن صاحبه، والله يبرئ ذمتك، وينفع به الميت.","link":"https://binbaz.org.sa/fatwas/2396/حكم-المال-الذي-توفي-صاحبه-وليس-له-ورثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_925.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6563,"question":"رجل أعطى مالًا لآخر، دون أن يشترط أن يرد المال مع زيادة، ولكن المدين من تلقاء نفسه رد المبلغ، ومعه ألف ريال زيادة، بنفس راضية، فهل هذا يعتبر ربًا؟","title":"حكم قضاء الدين بزيادة دون اشتراط ذلك","answer":"الجواب: إذا رد المبلغ بدون شرط، ولا تواطؤ على الزيادة؛ فلا بأس، النبي ﷺ يقول: إن خيار الناس أحسنهم قضاء الرسول ﷺ كان يعطي خيرًا مما أخذ -عليه الصلاة والسلام- ويقول: إن خيار الناس أحسنهم قضاء فإذا اقترض مائة، ورد مائة وخمسين، أو مائتين من باب المعروف، ومن باب المكافأة؛ فلا بأس، أو اقترض خمسين صاعًا من البر؛ فرد مائة، أو أقل، أو أكثر؛ فلا بأس، النبي ﷺ جاء أنه اقترض ثلاثين، ورد ستينًا، واقترض أربعين، ورد ثمانين. السؤال: أربعون ماذا؟ الشيخ: صاعًا، أو أربعين وسقًا.","link":"https://binbaz.org.sa/fatwas/2409/حكم-قضاء-الدين-بزيادة-دون-اشتراط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_936.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6571,"question":"هل قرض البنك العقاري يعتبر دينًا؟ وكيف إذا كانت روح الميت معلقة في دينه، فكيف الحل فيمن توفي وعليه دين للبنك؟","title":"حكم من توفي وعليه دين للبنك العقاري","answer":"الجواب: يعتبر دينًا، القروض التي للبنك العقاري ديون مثل بقية الديون، وإذا مات المستدين؛ قام الورثة مقامه، فإن التزموا في الآجال، والأقساط؛ فلا بأس، ولا يضره ذلك؛ لأنه لم يتحتم عليه التسديد الآن، لا يضر الميت، وهكذا الديون الأخرى التي في ذمته مؤجلة لا تضره إذا التزم الورثة بالحق، وتبقى على آجالها للبنك، وغير البنك. أما إذا لم يلتزموا فإنها توفى بسرعة، توفى من التركة بالعجلة، ولا تؤجل، أما إذا كانت الورثة، وقالوا: نحن نقوم مقامه، ورضي البنك، أو رهنوه، أو ضمينًا، فإن الديون تبقى على آجالها، وليس لأهلها حق في تعجيلها، إلا برضى من هي عليه، والميت لا يضره ذلك؛ لأن النفس المعلقة بالدين الذي هو حال الذي يلزم تسديده، أما الدين المؤجل؛ فلا يلزمه تسديده إلا في وقته.","link":"https://binbaz.org.sa/fatwas/2426/حكم-من-توفي-وعليه-دين-للبنك-العقاري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_953.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6586,"question":"أعمل بأحد البنوك، وأخذت قرضًا لتسديد السكن، حيث إن البنك يأخذ عمولة على هذا القرض، فما حكم الدين؟ وأيضًا رواتبنا من هذا البنك تتحصل من العمولة التي يحصلها البنك على المبالغ المقروضة لبعض العملاء، فما حكم الدين، وما حكم الراتب من هذا البنك؟","title":"حكم الاقتراض من البنك وأخذ الراتب منه","answer":"الجواب: أما الدين فلا يجوز، عليك أن ترد الأصل فقط، وليس لهم حق في الزيادة، وأما كون القرض تخصم من هذا البنك فالإثم على من أخذ الربا، أنت تأخذ راتبك، والبنك فيه الطيب والرديء، البنك فيه أشياء بحق، وأشياء بغير حق، ولست تعلم أن هذا من الربا، أو من غير الربا، أما كونك تعامل بالربا لا يجوز لك هذا، وما أخذته من الفائدة مائة فيها عشرة، أو فيها خمسة عشر ليس لك ذلك، هذا لا يجوز لك، وإذا كانت باقية عندك ليس لك تسليمها لهم.  السؤال: العمل في البنك؟ الجواب: لا يجوز عمله في البنك أيضًا؛ لأنه يعين على الإثم، والعدوان.","link":"https://binbaz.org.sa/fatwas/2395/حكم-الاقتراض-من-البنك-واخذ-الراتب-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_924.mp3","categories":["الربا والصرف","السلف والقرض"]},{"id":6980,"question":"هل الدين يمنع إجابة الدعاء، وإن كان في نفس صاحبه أن يقضيه؟ وإذا مات صاحب الدين وهو يريد أن يقضيه هل يقضيه الله عنه؟ وهل يحاسب عليه يوم القيامة إذا قضاه الله عنه؟ وهل تعلق روح المدين حتى يقضي ما عليه من الدين؟","title":"الدين لا يمنع الدعاء لمن كانت نيته الوفاء","answer":"الجواب: يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه فإذا أخذها وهو يريد الأداء، واجتهد، ولكن لم يتيسر له ذلك؛ قضاه الله عنه  وما ضره بقاؤه عليه، وفي الحديث: نفس المؤمن معلقة بدينه حتى يقضى عنه.  فإذا مات وقد نوى قضاءها، واجتهد في قضائها؛ فالله يقضيها عنه، ولا تعلق نفسه، لكن عليه بالاجتهاد والصدق، بالنيات الصادقة يكون معها العمل الصادق، فإذا كان نوى أن يقضيه؛ فعليه بالجد، والنشاط، والأخذ بالأسباب؛ حتى يقضي هذا الدين الذي  تحمله، أما أن يأخذ الدين ويقول: أنا أريد القضاء، وهو يلعب، ولا يبالي، ما هو صادق في نيته. والدين لا يمنع الدعاء، ولكن إذا كان بالنية -نية الوفاء- فهو على خير، أما إذا كان ظالمًا يريد أكل أموال الناس؛ فهذا خطر، قد يمنع دعاؤه، وقد تمنع إجابة أعماله، وقد يصيبه أضرار عظيمة بسبب أعماله القبيحة، قد يعاقب بعقوبات عاجلة، أو آجلة، لكن متى نوى قضاء الدين، واجتهد في الأسباب التي يقضى بها الدين؛ فهو على خير.","link":"https://binbaz.org.sa/fatwas/2894/الدين-لا-يمنع-الدعاء-لمن-كانت-نيته-الوفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1342.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7322,"question":"اشتريت قطعة أرض من صاحبها بالتقسيط على أربعة أعوام بمبلغ من المال، وبعد حوالي عام اتفقت معه على أن أسدده جميع الأقسام المتبقية دفعة واحدة، على أن يخفض من المبلغ المتفق عليه، فما رأي فضيلتكم في هذا؟ وهل تبدأ زكاتها منذ شرائها، أم بعد الإفراغ لي؟","title":"بيان الراجح في مسألة: (ضع وتعجل)","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم، وهي مسألة ضع وتعجل، وهي معلومة عند أهل العلم، ويروى أن النبي ﷺ قال لبني النضير لما أراد أن يجلهم، واشتكوا أن لهم ديونًا عند الناس، قال: ضعوا وتعجلوا.  فالصواب أنه يجوز إذا قال المدين: أنا أعطيك حقك دفعة واحدة، ولكن نزل عني، والدين أربعة آلاف على أربعة أعوام، فقال: أنا أنجزه لك إذا وضعت عني ألفًا، فقال صاحب الدين: نعم أنا أضع عنك ألفًا، واعطني ثلاثة آلاف، وأنا أسامحك، لا حرج في ذلك، الصواب أنه جائز، وإن كان كثير من أهل العلم يرى خلاف ذلك، لكن الصحيح أنه جائز؛ لأن هذا فيه مصالح تعجيل الحق، وبراءة الذمة، هذا فيه مصلحتان: تعجيل الحق لصاحبه ولو ناقصًا بدل ما يكون في سنوات يعطيه إياه حالًا، وتخفيفه على المدين يطيح عنه قطعة من الدين.  الصواب في هذا: أنه جائز، وهي مسألة: ضعوا وتعجلوا، يكون لك عند زيد ألف ريال تحل في رمضان الآتي، وقلت له: أعطيك ثمانمائة وسامحني الآن، إذا أعطيته ثمانمائة وسامحك عن المائتين لأجل التعجيل لا بأس، وهكذا ما كان أكثر وأقل.","link":"https://binbaz.org.sa/fatwas/3396/بيان-الراجح-في-مسالة-ضع-وتعجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1710.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7407,"question":"أخذت ذهب زوجتي، وقمت ببيعه برضاها بالكامل؛ لضائقة ألمت بي منذ خمسة عشر عامًا، وكان الثمن دينًا لها عندي، والآن وبعد ارتفاع ثمن الذهب عشرة أضعاف تطالبني بالقيمة الحالية، أو إعادة وزن الذهب لها، ماذا أفعل حتى تبرأ ذمتي من هذا الدين؟","title":"كيفية القضاء لمن استدان من امرأته ذهباً","answer":"الجواب: عليك أن ترد عليها ذهبها إذا كانت أعطتك الذهب وسمحت لك أن تبيعه وتنفقه في حاجاتك، فالذهب يعتبر قرضًا عليك وزنًا بوزن، فإن كنت بعته على حسابها، ورضيت بأن يكون القرض هو الثمن؛ فعليك رد الثمن، أما إن كان القرض الذي بينك وبينها نفس الذهب أن ترد عليها مثل ذهبها، فالمسلمون على شروطهم، يقول النبي ﷺ: المسلمون على شروطهم.  فإن كنت اتفقت معها على أن ترد عليها ذهبها، فرد عليها مثل ذهبها غالٍ أو رخيص، فإن كان الذي جرى بينك وبينها أنك تبيعه الذهب على حسابها، وأن الثمن يكون لها عليك، فالمسلمون على شروطهم، من شروطها الثمن أيضًا، والأحسن لك يا أخي أن تعطيها ما يرضيها، هذا أو هذا؛ لأن النزاع بينكما قد يفضي إلى ما لا تحمد عقباه، فوصيتي لك أن تعطيها الذي يرضيها، ولو كان فيه كلفة عليك، هذا هو الأصلح لك، قد أحسنت إليك ووسعت لك، فأرضها، يقول النبي ﷺ: إن خيار الناس أحسنهم قضاء.","link":"https://binbaz.org.sa/fatwas/3482/كيفية-القضاء-لمن-استدان-من-امراته-ذهبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1786.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7423,"question":"أخذت ذهب زوجتي، وقمت ببيعه برضاها بالكامل؛ لضائقة ألمت بي منذ خمسة عشر عامًا، وكان الثمن دينًا لها عندي، والآن وبعد ارتفاع ثمن الذهب عشرة أضعاف تطالبني بالقيمة الحالية، أو إعادة وزن الذهب لها، ماذا أفعل حتى تبرأ ذمتي من هذا الدين؟","title":"كيفية القضاء لمن استدان من امرأته ذهباً","answer":"الجواب: عليك أن ترد عليها ذهبها إذا كانت أعطتك الذهب وسمحت لك أن تبيعه وتنفقه في حاجاتك، فالذهب يعتبر قرضًا عليك وزنًا بوزن، فإن كنت بعته على حسابها، ورضيت بأن يكون القرض هو الثمن؛ فعليك رد الثمن، أما إن كان القرض الذي بينك وبينها نفس الذهب أن ترد عليها مثل ذهبها، فالمسلمون على شروطهم، يقول النبي ﷺ: المسلمون على شروطهم.  فإن كنت اتفقت معها على أن ترد عليها ذهبها، فرد عليها مثل ذهبها غالٍ أو رخيص، فإن كان الذي جرى بينك وبينها أنك تبيعه الذهب على حسابها، وأن الثمن يكون لها عليك، فالمسلمون على شروطهم، من شروطها الثمن أيضًا، والأحسن لك يا أخي أن تعطيها ما يرضيها، هذا أو هذا؛ لأن النزاع بينكما قد يفضي إلى ما لا تحمد عقباه، فوصيتي لك أن تعطيها الذي يرضيها، ولو كان فيه كلفة عليك، هذا هو الأصلح لك، قد أحسنت إليك ووسعت لك، فأرضها، يقول النبي ﷺ: إن خيار الناس أحسنهم قضاء.","link":"https://binbaz.org.sa/fatwas/3482/كيفية-القضاء-لمن-استدان-من-امراته-ذهبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1786.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7469,"question":"السؤال السابع -والأخ يعني الحقيقة شغل جزءاً كبيراً من الحلقة لكن لا نريد أن نهمل شيئاً من أسئلته- يقول: استدان رجل من رجل مبلغاً من الفرانسي والعربي فضة، وأراد أن يسدد ما عليه في هذه الأيام، فهل يجوز له أن يسددها ورقاً حسب سعرها في السوق أم لا؟ أفتونا أجاركم الله، ونريد الإجابة بالتفصيل حول هذه المسألة.","title":"حكم قضاء الدين إذا كان فضة ونحوها بالعملة الورقية","answer":"الجواب:  إذا كان على إنسان لآخر فرانسة أو فضة من عملة أخرى، فلا مانع أن يسدد ذلك ويقضي ذلك من العملة الورقية؛ لأن العملة الورقية جنس مستقل وذاك جنس مستقل، هذه من الورق وذاك من الفضة فلا منافاة، لكن يكون يداً بيد، يعطيه حاجته بسعر السوق يداً بيد عن الفرانسة وعن الدرهم الفضي الآخر. يعني: ينظر في قيمتها في الأسواق فيعطيه ما يقابل ذلك، يداً بيد، لا تأجيلاً بل يداً بيد، وإن أعطاه شيئاً آخر من باب الحيطة ومن باب الخروج من خلاف من لا يرى ذلك، مثل أن يعطيه عن ذلك سكر أو قهوة أو هيل أو خام أو أواني أو شبه ذلك، هذا حسن، يعني: بالسعر؛ لكن الأرجح عندنا والأظهر أنه لا حرج في أن يعوضه عن ذلك من العملة الورقية بالسعر حسب السوق. نعم.","link":"https://binbaz.org.sa/fatwas/4201/حكم-قضاء-الدين-اذا-كان-فضة-ونحوها-بالعملة-الورقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00206.mp3","categories":["السلف والقرض"]},{"id":7831,"question":"يقول: نحن مجموعة من الأشخاص عشرة أشخاص نشترك في جمعية تعاونية بقيمة خمسة وعشرين دينار شهرياً يدفعها كل شخص ويقبضها شخص بالتناوب، حيث تمر على الجميع في كل شهر، ما حكم ذلك؟ وهل هذا جائز أثابكم الله؟","title":"حكم الاشتراك في دفع مبلغ شهري ويقبضه أحدهم بالتناوب","answer":"الجواب: ما فيه بأس، إذا تعاونوا لا بأس بهذا المبلغ أو بأكثر أو بأقل، إذا تعاونوا عن سماح نفوسهم فلا بأس بهذا. نعم، هذا من باب التعاون على الخير. نعم.","link":"https://binbaz.org.sa/fatwas/5206/حكم-الاشتراك-في-دفع-مبلغ-شهري-ويقبضه-احدهم-بالتناوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05124.mp3","categories":["السلف والقرض"]},{"id":8000,"question":"هذه الرسالة من المدينة المنورة محمد عياد الجهني ، العنوان المدينة المنورة، دار الرعاية الاجتماعية طريق .. يقول فيها: سعادة سماحة فضيلة الشيخ عبد العزيز بن عبد الله بن باز! يسأل الشاب محمد عياد الجهني عن أنه أخذ دين من رجل ثم توفي الرجل ولم أعرف له أحداً أبداً وله مدة طويلة متوفى ذلك الرجل، فماذا أفعل، أفتوني في أمري جزاكم الله عنا خير الجزاء وشكراً لكم؟","title":"كيفية قضاء الدين المتوفى صاحبه","answer":"الجواب: إذا كان عند الإنسان دين أو رهن أو وديعة لآخر ولم يعرف ورثته بعد موته، وسأل واجتهد ولم يعرف أحداً يتصدق بها في وجوه البر مثل على فقراء، مثل يجعلها في عمارة مسجد مشاريع أخرى إسلامية حتى ينفع الميت، بالنية ... عن صاحبها، بشرط أنه اعتنى واجتهد وسأل عن أقاربه ولم يجد أحداً، يعني: ما وجد من يدله بعد الاجتهاد فإنه يتصدق بها على الفقراء أو يصرفها في تعمير مسجد، أو نحوه من المشاريع الخيرية، ولو سلمها للحاكم القاضي في البلد وأخذ سنداً عليها من عنده كفى، لكن إنجازها وصرفها في وجوه الخير أسرع في الخير وأنفع لصاحبها؛ لأنه يؤجر على ذلك إذا تصدق بها عنه، نعم ، بالنية. نعم.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5567/كيفية-قضاء-الدين-المتوفى-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07409.mp3","categories":["السلف والقرض"]},{"id":8280,"question":"لقد عرفت منزلة المقرض عند الله وأحب أن أخوض في هذا العمل ولكن المشكلة أن والداي لا يرضيان بذلك؟","title":"منع الوالدين للولد من الإقراض","answer":"الجواب: لكي أن تقرضي من غير علمهما لأنهما ليس لهما أن يمنعاك من الأمر الشرعي ولكن ينبغي أن تظهري طاعتهما في ذلك حتى لا يكون بينكما شر، فالرسول عليه السلام قال: إنما الطاعة في المعروف وليس من المعروف منعك من التوسيع على إخوانك في الله وأخواتك في الله ليس هذا من المعروف وإذا كانا يخشيان ذهاب المال فاحتاطي وأقرضي بالرهن بالضمان جمعاً بين المصالح بين حفظ مالك وبين إرضاء والديك وإذا كانا لا يسمحان ولو بالضمان ولو بالرهن فأقرض سراً ولا حرج عليك في ذلك.\nالمقدم: بارك الله فيكم هذا إذا كان القرض للبشر لكن إذا كان لله سبحانه وتعالى .. فكيف تنصحونها؟\nالشيخ: هذا العمل الصالح عليها أن تجتهد في الأعمال الصالحات مطلقاً لكن إذا كان والداها لا يرضيان بأن تصوم مثلاً ويقولان: إن هذا يشق عليك أو كذا أو كذا فإنها تصوم سراً ولا تبدي لهما بشيء من ذلك أو في أيام الشتاء حتى لا يفطن لذلك، لأن طاعة الوالدين لها شأن عظيم وهما لهما العناية العظيمة بأولادهما من الرحمة والعطف والخوف على الولد أو البنت فإذا جاملتهما وأظهرت يعني الموافقة على رأيهما فلا بأس بذلك من باب المجاملة ومن باب تطييب النفس حتى لا يكون في نفوسهما عليها شيء وهي تنتهز الفرص في الأوقات المناسبة وإذا تركت الصيام طاعة لهما فلا شيء يرجى لها في ذلك الخير العظيم وثواب الصائمين.\nإذا لم يتيسر لها أن تصوم سراً لأنهما يعرفان ذلك تدع الصيام ولا تشاق والديها ليس لها أن تشاق والداها بل تلاحظ رضاهما لأن برهما واجب والصوم النافلة تطوع فإذا كانا لا يسمحان ويشق عليهما وربما ضرباها أو هجراها تترك ذلك، نعم. من باب ترك المستحب لحفظ الواجب.\nالمقدم: بارك الله فيكم، إذاً القرض في جانب الله تعالى لا يقتصر على القرض المادي المعروف بالدينار والدرهم.\nالشيخ: إِنْ تُقْرِضُوا اللَّهَ قَرْضًا حَسَنًا [التغابن:17] يعني بالطاعة.\nالمقدم: بالطاعة بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6088/منع-الوالدين-للولد-من-الاقراض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10606.mp3","categories":["السلف والقرض"]},{"id":8800,"question":"السؤال الثالث في رسالة الأخ سعد موسى السويرق الصلاحي من الحجرة في بلاد زهران يقول فيه: سبق وأن أخذت مبلغاً من المال من أحد زملائي في العمل عن طريق السلف، وصدر قرار بنقلي إلى المنطقة الشرقية ولم أقابل هذا الشخص لمدة لا تقل عن عشر سنوات، لذا أرجو الإفادة عن هذا المبلغ ماذا أفعل به، أفيدونا جزاكم الله خيراً؟","title":"حكم المال المستقرض الذي لم يعرف صاحبه","answer":"الجواب: الواجب عليك أن تسأل عن صاحبك أهل خبرته وأهل معرفته تسأل عنه العارفين به بالمكاتبة بالهاتف بكل وسيلة، فمتى وجدته أرسلت حقه إليه، وإن كان قد مات تعطيه ورثته، تسأل عن ورثته وتعطيهم الحق، فأما إذا عجزت ولم تعرف حاله ولا ورثته فإنك تتصدق به عنه بالنية.. تتصدق به على بعض الفقراء بالنية عن صاحبك والله جل وعلا يثيبه على ذلك وينفعه بذلك وأنت تبرأ بعد العجز وبعد الحرص على معرفة محله أو ورثته إن كان قد مات إذا عجزت عن هذا كله فإنك تتصدق بهذا المال بالنية عن أخيك الذي مات تتصدق به عنه والله يأجره ويبرئ ذمتك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6958/حكم-المال-المستقرض-الذي-لم-يعرف-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22205.mp3","categories":["السلف والقرض"]},{"id":8950,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: التائب إلى الله (م. م. ط) من القصيم، أخونا بدأ رسالته بعبارات هي مشاعر السادة المستمعين نحو هذا البرنامج فبدأ يقول: دعواتنا الخالصة لكم ولفضيلة الشيخ عبدالعزيز بن عبدالله بن باز بموفور الصحة والعافية لما تقدمونه من خدمات جليلة التفضل بالإجابة على استفساراتنا نحن العبيد الضعفاء إلى الله سبحانه وتعالى، جعلكم الله نبراسًا بعلمكم ينتفع به المسلمون وسائر الناس ولكم شكرنا.فضيلة الشيخ! لي سؤال أرجو أن تتفضلوا بالإجابة عليه: كنت أعمل مهندسًا ببلدنا وأدير عملًا وعندما أردت الدخول بموضوع الزواج احتجت إلى مبلغ من المال ليس بصغير وقتها يقدر بألف وخمسمائة جنيه، فاستدنت لأتمم زواجي من أحد المقاولين الذين يعملون معي وبعدها لم أقدر على سداد دينه، المهم حاولت تعويضه من مال الشركة بإضافة بعض الأعمال التي لم تعمل بما يوازي المبلغ وصرف فلوسه من الحكومة، والآن أنا أعمل هنا بالسعودية، وعندما سمعت برنامجكم وجدتني أنجذب إليه لعلي أجد عنده الحل، هل عقد الزواج صحيح في هذه الحالة، حيث أنها نقود ليست بحلال؟ثانيًا: ماذا أفعل الآن حيث أني لا أقدر على رد هذا المبلغ؛ لأنه ليس لشخص وإنما للحكومة، أنا الآن والحمد لله تائب وأصلي وأصوم وأقوم بسائر العبادات إلا أن هذه الخطيئة كثيرًا ما تضايقني وتقلقني أرجو التوجيه جزاكم الله خيرًا؟","title":"حكم قضاء الدين الخاص بالدولة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفأسأل الله عز وجل أن يمن علينا وعليك بالتوبة النصوح، وأن يصلح لنا ولك ولجميع المسلمين القلب والعمل.\nوالواجب عليك في هذا الواقع أن ترد هذا المال إلى الدولة؛ لأنه من مال الدولة مع التوبة إلى الله عز وجل، فإذا استطعت أن ترده إلى الدولة فعليك أن ترده إلى الدولة؛ لأنه أخذ من بيت المال فإن لم تستطع فيصرف هذا المال في وجوه البر، كتعمير المساجد وإصلاح دورات المياه، والصدقة على الفقراء ونحو ذلك، مع التوبة الصادقة والله يتوب على التائبين، وأما النكاح فصحيح والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7107/حكم-قضاء-الدين-الخاص-بالدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17301.mp3","categories":["السلف والقرض"]},{"id":9083,"question":"وبعث المستمع محمد عبد الله السبيعي برسالة للبرنامج يقول فيها:السلام عليكم ورحمة الله وبركاته. وبعد: قمت بطلب عمال من الخارج، فلما وصلت إليهم في بلدهم احتجت مبلغاً من المال وأخذت منهم ما يعادل ألفين وخمسمائة ريال، فلما وصلوا إلى مكاني أي: في بلدي هنا في السعودية وجدتهم لم يعرفوا عن المهنة أي شيء، فقلت لهم: اشتغلوا تحت التجربة لمدة ثلاثة شهور، ولكنهم رفضوا فحاولت معهم لعدة مرات فرفضوا، فقمت بتسفيرهم إلى بلادهم ولم أعطهم حقهم إلا القليل، مع العلم أنني خسرت عليهم ما يعادل الذي أخذته منهم، وأنا مستعد أن أعطيهم حقهم، ولكن لا أعرف عنواناً لهم أرجو إفادتي ماذا أفعل أفادكم الله؟","title":"أهمية إرجاع الحقوق إلى أهلها","answer":"الجواب: هذه مسألة خصومة تحتاج إلى نظر من جهة القاضي حتى يعلم دعواك عليهم وحتى يعلم جوابهم، لكن إذا دفعت إليهم حقوقهم التي اتفقت معهم عليها من باب الحيطة فهذا حسن، ترسل حقوقهم إلى المكتب الذي تم التعاقد معهم فيه، وترسل لهم القرض الذي أخذته منهم، والمسلم أخو المسلم لا يظلمه ولا يخذله ولا يحقره ولا يتعدى عليه ولا يخونه، فإما أن تخاصمهم شرعاً عند القاضي عند المحكمة حتى تعرف ما لك وما عليك وتعطيهم حقوقهم على بينة، وإما أن تسمح بدفع حقوقهم إليهم وإرسالها إليهم، وما عند الله خير وأبقى، وترسل إليهم أيضاً القرض الذي أخذته منهم، وهذا خير لك في الدنيا والآخرة، وأبشر بالخلف والخير والعاقبة الحميدة إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/7248/اهمية-ارجاع-الحقوق-الى-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22610.mp3","categories":["السلف والقرض"]},{"id":9330,"question":"الرسالة التالية وصلت إلى البرنامج من شقراء بتوقيع أحد الإخوة يقول: (ص. ع. م) أخونا يقول في رسالته: المعروف حالياً أن الناس يأخذون من بعضهم أموالاً كقرضة ويسمونها ديناً وهي غير السلف، وسؤالي: هل الدين بالمفهوم الحالي حرام، وما هي الطريقة الإسلامية الشرعية لذلك، أفيدونا بذلك وجزاكم الله خيراً؟","title":"الفرق بين القرض والسلم","answer":"الجواب:  ليس الدين حراماً إذا كان على الوجه الشرعي، وليس القرض حراماً إذا كان على الوجه الشرعي ويسمى ديناً أيضاً، قال الله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ[البقرة:282]، فالله سبحانه أباح لعباده المؤمنين التداين، وأن يكتب ذلك الدين إلى أجل، فلا بأس بالمداينة ولا بأس بالاقتراض، والمداينة كأن تشتري من أخيك سلعة من أرض أو بيت أو دكان أو سيارة أو غير ذلك إلى أجل معلوم لحاجتك إليها، لتسكن البيت، لتزرع الأرض، لتستعمل السيارة، أو لتستفيد منها تبيعها وتستفيد منها إلى غير ذلك من المقاصد، هذه تسمى مداينة إلى أجل مسمى، هذا شيء لا حرج فيه إذا كان المبيع مملوكاً للبائع وفي حوزة البائع فإن هذا البيع يسمى بيعاً ويسمى ديناً. ومن المداينة ما يسمونه بالسلم وهو: أن تأخذ من شخص دراهم معينة معجلة يشتري بها شيئاً من ذمتك كقهوة، سكر، رز غير ذلك، تأخذ منه مثلاً عشرة آلاف ريال على أنك تعطيه بكل ريال صاعاً من الحنطة نوعها كذا أو صاعاً من الأرز بعد سنة بعد سنتين بعد أشهر معينة هذا يسمى السلم ويسمى السلف، وهو ما عجل ثمنه وأخر مثمنه، إذا كان معلومًا تامة شروطه إلى أجل معلوم، أو سيارة قد علم موديلها وصفاتها الكاملة تبيعها عليه من ذمتك إلى أجل معلوم فتأخذ منه عشرة آلاف أو عشرين ألفًا على أنك تدفع له بعد سنة أو بعد سنتين سيارة صفتها كذا وصفتها كذا وموديلها كذا معروفة ليس فيها شبهة، أو آصعًا معلومة من الأرز أو من الحنطة أو من غير ذلك أو من القهوة أو من السكر إلى غير ذلك، شيء معلوم، قال النبي ﷺ لما قدم المدينة وهم يسلفون الثمار السنة والسنتين قال عليه الصلاة والسلام: من أسلف فليسلف في كيل معلوم ووزن معلوم إلى أجل معلوم هذا كله يسمى مداينة. ومنها القرض أيضاً كأن تقول لأخيك في الله أو لأخيك من النسب أو لابن عمك أو لصهرك أبي زوجتك أو أخي زوجتك أو غيرهم تقول له: أقرضني كذا، أقرضني ألف ريال، أقرضني عشرة آلاف ريال قرضاً بدون فائدة لله، هذا يسمى دينًا ويسمى قرضًا، فإذا أعطاك أخوك في الله أو قريبك أو صهرك مطلوبك من المال فهذا يسمى قرضًا، إذا كان من دون فائدة مجرد احتساب، هذا يسمى قرضًا؛ لأنه إرفاق، ويسمى ديناً؛ لأنه في الذمة، فهذا لا حرج فيه ولا بأس به. لكن لو قال: على أن تعطيني زيادة كذا وكذا صار ربا، لو قال: نعم، أنا أعطيك قرض عشرة آلاف لكن بشرط أن تعطيني في كل ألف عشرة أو مائة أو خمسين من أجل التأخير الذي يتأخر المال عندك هذا هو الربا المعروف لا يجوز، أو قال: أنا أعطيك عشرة آلاف قرضاً لكن على أن تعطيني سيارتك الفلانية أستعملها شهرين ثلاثة أكثر أقل في مقابل هذا القرض، هذا لا يصلح؛ لأنه قرض بشرط وهذا لا يجوز. كذلك لو قال: نعم، أنا أعطيك عشرة آلاف أو مائة ألف قرضاً على أن تعطيني أرضك الفلانية أزرعها وأستفيد منها حتى تعطيني قرضي، حتى يستفيد من الأرض بدون أجر في مقابل هذا القرض، أما إن استأجرها بأجرة المثل من دون شرط استأجرها بالعادة بنصف الزرع بثلث الزرع بآصع معلومة، بدراهم معلومة، كما يستأجرها الأجنبي من دون شرط بينكم وقد استأجرها بعد ذلك منك فلا بأس، لكن الله يعلم ما في القلوب، إذا كانت من دون شرط وبالأجرة المعتادة التي يأخذها غيره. نعم. المقدم: الصور الموجودة في السوق، لعل سماحة الشيخ بلغه بعض منها؟\nالشيخ: نعم، وهي؟ المقدم: وهي كأن يأتي إنسان محتاج إلى تاجر يبيع ويشتري في أقمشة أو في مواد غذائية أو نحو ذلك، ويقول: تشتري هذه البضاعة بمبلغ كذا وتسدد القيمة بعد عام بمبلغ كذا وكذا، بطبيعة الحال المبلغ يكون زائد لكن ذلك المحتاج لا يستلم تلك البضاعة.\nالشيخ: هذا ما يصلح، هذا يسمونه التورق ولكن يسيئون الاستعمال، ويسمونها العامة: الوعدة ويسيئوا الاستعمال، يبيع المال وهو ..... جالس ما يقبض، وهكذا الآخر يبيعه وهكذا الآخر، لا ما يصلح هذا، التجارة الشرعية والمداينة الشرعية أن يشتري مالاً موجوداً عند البائع في حوزة البائع ثم يقبضه المشتري ويحوزه المشتري ويتصرف فيه، باستعماله إن كان أرضاً باستعمالها إن كانت سيارة، بغير ذلك من أنواع الاستعمال يعني: يقبضه، هذا هو البيع الشرعي، أما أن يشتري منه هذا المال الموجود ...... ثم يتركه ويبيعه عند البائع يبيعه على زيد أو على عمرو، هذا ما يجوز، نعم. هذا فيه الحديث الصحيح: لا تبع ما ليس عندك، لا يحل سلف وبيع ولا بيع ما ليس عندك. نعم.","link":"https://binbaz.org.sa/fatwas/7480/الفرق-بين-القرض-والسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15504.mp3","categories":["البيوع","السلف والقرض"]},{"id":9379,"question":"اشتريت فاكهة من بائع أمام إحدى البقالات وحينما دفعت الحساب وجدت أن ما معي من نقود لا تكفي فطلب مني البائع إحضار الباقي مرة أخرى، وحينما رجعت بعد مدة لمكان البائع لم أجده، وسألت صاحب البقالة فقال: إنه ترك البيع معه ولا يعلم له مكان، ورفض صاحب البقالة استلام المبلغ مني، والآن أسأل كيف أتصرف بذلك الدين الذي لم أجد صاحبه؟","title":"حكم من عليه دين لم يجد صاحبه","answer":"الجواب: إذا كان على الإنسان دين ولم يعرف صاحب الدين، بأن: انتقل إلى مكان آخر أو سافر، وهكذا لو كان عنده وديعة أو عارية وذهب صاحبها ولم يدر عنه ولم يعرفه فإنه بعد التحري وبعد بذل المستطاع في التعرف عليه أو على مكانه إذا عجز فإنه ينتظر المدة المناسبة لعله يأتي صاحبه إليه إن كان يعرفه، وإن لم يأت فإنه يتصدق بذلك على الفقراء والمساكين، أو يصرف ذلك في بعض المشاريع الخيرية، كتعمير المساجد ودورات المياه وما أشبه ذلك من المشاريع الخيرية، ويكون الأجر لصاحبه، ينويه عن صاحبه عن صاحب المال، والله يوصل إليه أجره .\nلكن إذا تريث بعض المدة لعله يأتي من باب الاحتياط فحسن، ثم إذا جاء صاحب الحق فهو بالخيار، إن شاء قبل الصدقة وصارت له الصدقة، وإن شاء طلب حقه فتعطيه حقه ويكون الأجر لك فيما تصدقت به. نعم.","link":"https://binbaz.org.sa/fatwas/7543/حكم-من-عليه-دين-لم-يجد-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18702.mp3","categories":["السلف والقرض"]},{"id":9490,"question":"وهذه رسالة من المستمع حسن ساتي سوداني مقيم بالسعودية، يقول في رسالته: كنت أعمل عامل بقالة مع أحد الرجال، وقام أحد الناس بشراء بعض المقاضي بالدين، وصاحب البقالة يعلم بذلك، ووعد المدين بسداد الدين عندما يتيسر له ذلك، وقمت بإجازة سنوية لبلدتي وفي ذلك الوقت طالب صاحب البقالة المدين بالدين الذي عليه، فأنكر ذلك وقال: إنه لم يستدين شيء من البقالة، انتهز فرصة غيابي وعند عودتي من الإجازة لم أجد الرجل المستدين وقد ترك المنطقة نهائيًا، وقام صاحب البقالة بمطالبتي بسداد المبلغ المطلوب من الرجل.هل الدين الذي أنكره الرجل أصبح في ذمتي، وهل يجوز أن نقتسم المبلغ بيننا باعتباره صاحب البقالة عنده علم بالدين، أفيدونا أفادكم الله؟","title":"حكم سداد العامل دين المشترين للمالك إذا لم يسددوا","answer":"الجواب: هذا فيه تفصيل: إذا كان صاحب البقالة قد أذن لك أن تدين الناس، إذا كان قد أذن لك وسمح لك بهذا فلا حرج، ولكن عليك مع ذلك أن تثبت الدين، إذا كنت ....... ولم تثبه في دفتر ولا بشهود فأنت تغرم المال؛ لأنك مفرط.\nوإذا كان ما أذن لك بأن تدين أحدًا فأنت تضمن المال أيضًا.\nأما إذا كان أذن لك فلا بأس عليك لكن تثبت الدين إما بالشهود وإما بالكتابة، يكتب على نفسه وتأخذ توقيعه حتى لا يخدعك، وحتى لا يضيع المال، فإذا كنت ما أشهدت عليه ولا كتبت عليه أو كان صاحب البقالة ما أذن لك في إدانة الناس فإنك تضمن هذا المال.\nوإذا بقي إشكال فالمحكمة تنظر في أمرك، إذا كان هناك إشكال وغير ما ذكر فالمحكمة تنظر في الأمر، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7654/حكم-سداد-العامل-دين-المشترين-للمالك-اذا-لم-يسددوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19209.mp3","categories":["السلف والقرض"]},{"id":9687,"question":"وهذه رسالة وردت من حمد فراج هزاع من الكويت الصليبخات يقول فيها: أنا سوف أتقاعد عن العمل والحكومة تعطي الأفراد المتقاعدين مبلغ ستة آلاف دينار ويحصلونها منهم، في كل شهر خمسين ديناراً من راتب التقاعد المقبل حتى يعاد لهم هذا المبلغ فهل هذا جائز أم لا؟","title":"حكم القرض من الحكومة وتسديده من الراتب مقسطاًَ","answer":"الجواب: ما نعلم فيه شيء، هذا سلفة قرض، إذا أعطته الدولة ستة آلاف دولار أو دينار ثم تأخذه منه مقسطاً على خمسين كل شهر ما نعلم في هذا شيء، إذا كان ما فيه شيء من المحذورات الأخرى ما بين، أما مجرد أنها تعطي الموظف لديها عند قربه من التقاعد، أو قبله بمدة ستة آلاف أو أقل أو أكثر على أنه يسدد لهم هذا المبلغ مشاهرة في كل شهر يعطيهم خمسين أو أقل أو أكثر ما نعلم فيه شيء.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7849/حكم-القرض-من-الحكومة-وتسديده-من-الراتب-مقسطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25208.mp3","categories":["السلف والقرض"]},{"id":10090,"question":"مواطن مصري اسمه حسين عبد الحميد بعث يقول: لي خال توفي وفي ذمتي له ألف وخمسائة جنيه، كيف أتصرف في هذا المبلغ، هل أتصدق به؟ أم أحج عنه؟ أم أسلمه للورثة؟ أم كيف توجهونني، جزاكم الله خيرًا؟","title":"حكم من كان عليه مال لشخص فتوفي صاحب المال","answer":"الجواب: عليك أن تسلمه للورثة، إذا مات إنسان وله دين عند الناس، فعلى من عنده الدين أن يسلم الدين الذي عنده للورثة، هذا يجب عليه وجوب، من كان عنده دين لأحد فإنه يسلمه لورثته إذا مات، ولا يكتم ذلك ولا يتصدق به بل يعطيه الورثة. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8259/حكم-من-كان-عليه-مال-لشخص-فتوفي-صاحب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27618.mp3","categories":["السلف والقرض"]},{"id":10754,"question":"المستمع (م. ن. س) من الصومال، ويعمل في المملكة بعث برسالة يقول فيها: توفي والدي وأنا صغير السن، وبعد أن كبرت سمعت أن عليه ديناً، ولا أعلم مقدار هذا الدين ولا من هو صاحب الدين، كما أن الذي أخبرني عن هذا الدين توفي إلى رحمة الله تعالى دون أن أعرف منه صاحب الدين، فكيف أعمل لأبرئ ذمة والدي من هذا الدين الذي لا أعرف مقداره، ولا من هو صاحبه، أفيدوني جزاكم الله خيراً؟","title":"حكم من كان على أبيه دين ولم يعرف صاحبه ولا مقداره","answer":"الجواب: لا يلزمك شيء يا أخي! ما دمت لا تعلم أهل الدين ولم يطالبك أحد، فلا يلزمك شيء الحمد لله، إلا إذا علمت ديناً بالبينة الشرعية ولوالدك تركة توفي من التركة، وإن كنت أوفيت من مالك جزاك الله خيراً، أما ما دام الأمر هكذا لا تعلم الدين ولا أهل الدين ولم يطالبك أحد فلا شيء عليك، والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8935/حكم-من-كان-على-ابيه-دين-ولم-يعرف-صاحبه-ولا-مقداره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34705.mp3","categories":["السلف والقرض"]},{"id":10945,"question":"السؤال الأخير لأخينا يقول: هناك ما يسمى: بالجمعية وصفتها: أن يقوم مجموعة من الموظفين بالاتفاق فيما بينهم على أن يدفعوا لأحد أعضاء هذه المجموعة مبلغ ألف أو ألفين ريال عن كل عضو من المجموعة لعضو واحد لشهر محرم مثلًا، وفي شهر صفر يدفعون نفس المبلغ لعضو آخر من هذه المجموعة، فهل يدخل ذلك في الحديث: كل قرض جر نفعًا فهو ربا؟","title":"حكم الجمعية التي تقام بين الموظفين","answer":"الجواب:  الصواب أنه -إن شاء الله- لا يدخل في ذلك، وقد درس مجلس هيئة كبار العلماء هذا الموضوع، وقرر أنه لا حرج في ذلك -إن شاء الله- لأنه سلف، ليس فيه زيادة، بل هم متساوون في ذلك، فلا حرج في ذلك -إن شاء الله- نعم. المقدم: سماحة الشيخ! الواقع أن هذه الجمعيات منتشرة كثيرًا، ويغلب عليها أن أحد الأعضاء لو لم يشترك لا يسلفوه؟ الشيخ: نعم، لأنهم لعله يوفي معهم في الدائرة، أو في الشركة، أو نحو ذلك، فالحاصل أن هذا يدفع ألفين وهذا يدفع ألفين وهذا يدفع ألفين والشهر الآخر كذلك، وهكذا حتى ينتهوا، فليس فيه شرط زيادة، إنما هم اتفقوا على هذا القرض المعين الذي ليس فيه زيادة. المقدم: لكن الشرط بينهم أن لابد من اشتراكك في الدفع شهريًا؟ الشيخ: هذا هو. المقدم: والذي لا يشترك لا يعطى؟ الشيخ: نعم هذا هو ليس فيه زيادة. المقدم: وهذا لا يعد نفعًا؟ الشيخ: ما يضر الإنسان؛ لأنه نفع مشترك كله سواء، ما في زيادة لأحد على أحد. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9130/حكم-الجمعية-التي-تقام-بين-الموظفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36314.mp3","categories":["السلف والقرض"]},{"id":11128,"question":"هل يجوز السلف من الشعير بالشعير الذي يعد علفًا للأغنام إلى أجل، ثم يرده مثلًا بمثل؟","title":"حكم السلف في الشعير","answer":"الجواب:  لا بأس، الشعير وغير الشعير، الشعير والبر والرز والدراهم، كلها يجوز السلف ويرد مثله.  المقدم: مثلاً بمثل؟ الشيخ: نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9311/حكم-السلف-في-الشعير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36911.mp3","categories":["السلف والقرض"]},{"id":11231,"question":"تقول: لي صديقة أخذت مني بعض الأشياء ولم تردها، وأخجل أن أطالبها بها، فهل لي أن أنوي من جديد بأنها صدقة عليها؟","title":"حكم من أدان صديقه شيئاً فلم يرده فنواه صدقة","answer":"الجواب: لا مانع إذا سامحتيها جزاك الله خيرًا، بلغيها أنك أبرأتيها وأنك سامحتيها، هذا طيب، وإن طالبتيها حقك فلا بأس، إن طلبت قلت: يا فلانة! أرجو تردين علي حقي، ... لا بأس، الحمد لله، وإن سامحتيها وأبرأتيها فأخبريها ولك أجر الصدقة. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9422/حكم-من-ادان-صديقه-شيىا-فلم-يرده-فنواه-صدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37319.mp3","categories":["السلف والقرض"]},{"id":11488,"question":"بعد هذا ننتقل إلى المدينة المنورة عبر رسالة بعثت بها إحدى الأخوات المستمعات تقول أم عاتقة، أختنا تقول: أقرضت شخصًا مبلغًا من المال، وبعد فترة ودون تأثير من قبلي، أو تضييق ذهب، واحتال للحصول على المال، وأعطاني إياه سدادًا لدينه، فهل يجوز لي أخذه؟ جزاكم الله خيرًا.","title":"سداد الدين من مال حرام","answer":"الجواب:  إذا كنت تعلمين أن هذا المال سرقة، أو غصب؛ فلا تأخذيه، أما إذا كنت لا تعلمين؛ فليس عليك حرج، الإثم عليه، أما أن تعلمي؛ فلا تساعديه على الباطل، من علم أن هذا المال الذي أتى به الشخص حرام، نهبة أو سرقة أو من معاملة ربوية؛ لا يقبله ....... ينصح الشخص، ويعظه ويذكره ويحذره، نعم. المقدم: جزاكم الله خيرًا، إذا كان سأل الناس حتى أعطوه سماحة الشيخ؟ الشيخ: إذا سأل الناس، فأعطوه؛ فلا بأس، إن كان صادقًا؛ فلا حرج عليه، وإن كان كاذبًا؛ فالإثم عليه. المقدم: مدين كونه مدين؟ الشيخ: هذا عذر. المقدم: هذا عذر؟ الشيخ: عذر شرعي، المدين الذي لا يجد وفاءً؛ يسأل، نعم. المقدم: نعم، الله المستعان، جزاكم الله خيرًا، كأني بسماحة الشيخ يقول: إذا كان هذا المال حصل عليه هذا المدين عن طريق سؤال الناس؛ فليس باحتيال؟ الشيخ: ... لا بأس إذا كان عن حاجة، غارمًا وسأل الناس؛ فلا بأس إذا أخذه من الناس، وسدد. فالمقصود أن المدين الغارم العاجز له أن يسأل، يقول النبي ﷺ: إن المسألة لا تحل إلا لأحد ثلاثة: رجل تحمل حمالة؛ فحلت له المسألة حتى يصيبها، ثم يمسك هذا منهم في الغالب، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9669/سداد-الدين-من-مال-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38302.mp3","categories":["السلف والقرض"]},{"id":12261,"question":"المستمع عبدالله أحمد من اليمن الشمالي، بعث برسالة يقول فيها: أخذت من والدي كبشًا بمبلغ ستمائة ريال، وقلت له: سوف أعطيك سبعمائة، أو ثمانمائة ريال عوضًا عنها، فهل هذا ربا، أم لا؟ وهل الحكم واحد؛ فيما إذا كان الشخص غير والدي،؟ أرجو الإفادة جزاكم الله خيرًا.","title":"حكم قضاء الدين بأكثر منه","answer":"الجواب:  إذا اشتريت سلعةً من أبيك، أو غيره بستمائة ريال، أو بأكثر، ثم عند الوفاء زدته؛ لأنك تأخرت عنه، وقدرت له صبره عليك؛ فلا بأس، أما إن كانت الزيادة طلبها منك، وشرطها عليك من أجل التأخير، هذا ربا لا يجوز، قال: ما أسمح عنك إلا أن تزيدني، ما أسمح أنك تتأخر، عجل، قلت ..: أمهلني وأنا أزيدك، بدل الست، أعطيك سبع، من أجل الإنظار، هذا لا يجوز، هذا ربا. أما عند القضاء أعطيته من نفسك، عن طيب نفس، لا عن شرطٍ بينك وبينه، فهذا لا بأس، يقول النبي ﷺ: إن خيار الناس أحسنهم قضاء والنبي ﷺ كان يقضي أخير مما أخذ، عليه الصلاة والسلام. والخلاصة أنه إن كان شرطًا فلا يجوز، أما إن كان إحسانًا منك؛ لأنه أمهلك، وأنظرك، أو لأنه أبوك تحب له الخير، وأردت أن تزيده؛ فلا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10461/حكم-قضاء-الدين-باكثر-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44912.mp3","categories":["السلف والقرض"]},{"id":12393,"question":"الواقع سماحة الشيخ هذا الموضوع يكاد يكون ظاهرة بين كثير من الناس، إذا اقترض أحدهم لا يهتم بالوفاء، فما هو توجيه الشيخ؟","title":"الترهيب من المماطلة في أداء الديون لأصحابها","answer":"الجواب:  هذا لا يجوز، هذا منكر، النبي ﷺ يقول: مطل الغني ظلم ويقول: لي الواجد يحل عرضه وعقوبته فالواجب عليه إذا اقترض أن يبادر بالأداء في الوقت المحدد، وعند اليسر بالأداء، إذا كان محددًا؛ يبادر، وإن كان ما هو محدد متى أيسر؛ قضى، ولا يجوز له المطل، ولا التأخير مع اليسر، أو مع حضور الوقت الذي حدد له المقرض، وهذا التساهل يسبب منع هذه المصلحة، وتساهل الناس في القرض، وامتناعهم منه بسبب فعل بعض الناس الذين لا يبالون بالقرض، ولا يسددون، ويماطلون؛ لأنهم بهذا يسببون منع الآخرين من القرض. فالمقصود: أن الواجب على من اقترض أن يعتني بالتسديد حين يقدر على التسديد، أو حين يحضر الوقت المحدد وهو قادر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10599/الترهيب-من-المماطلة-في-اداء-الديون-لاصحابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40118.mp3","categories":["السلف والقرض"]},{"id":12473,"question":"يقول: كان هناك صديق يمر بضائقة مالية، فأراد أن يقترض بعض المال من أحد الأصدقاء، ولكن بعض الناس قالوا له: لا تقترض منه؛ لأن ماله حرام، ولأنه يعمل في التماثيل القديمة، هل لا بد للإنسان إذا اقترض مالًا من أخيه أن يسأله عن مصدره، أو أن يسأل عن مصدره؟ وهل إذا كان يأتي عن طريق غير مشروع، فهل على الإنسان إثم إذا اقترض؟ نرجو التوجيه جزاكم الله خيرًا.","title":"حكم الاقتراض من شخص كسبه حرام","answer":"الجواب:  إذا كان يعلم أن اكتسابه حرام، وأن ماله حرام؛ لا يقترض منه، وأما إذا كان لا يعلم؛ فلا يلزمه السؤال، يقترض من أخيه، والحمد لله، والأصل السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10674/حكم-الاقتراض-من-شخص-كسبه-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40415.mp3","categories":["السلف والقرض"]},{"id":12694,"question":"المستمع (م. أ. س) من الرياض بعث يسأل ويقول: فضيلة الشيخ: علي دين لصديقي، انقطع الاتصال به، ولا أدري عنوانه الآن، والآن أريد أن أسدد ما علي، فما الوسيلة؟ أفيدوني جزاكم الله خيرًا.","title":"حكم من عليه دين لا يعرف مكان صاحبه","answer":"الجواب:  المشروع لك أن تتصدق به عنه، والله -جل وعلا- ينفعه بذلك، وتبرأ ذمتك، ومتى جاء إليك يطلب حقه؛ خيِّره، فإن أمضى الصدقة؛ فهي له، وإن لم يمضها؛ كان لك أجرها، وتعطيه حقه، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10904/حكم-من-عليه-دين-لا-يعرف-مكان-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41804.mp3","categories":["السلف والقرض"]},{"id":12695,"question":"استلفت مبلغًا من المال من خالي لعلاج والدي، ولم يتيسر لي سداد المبلغ بعد ذلك، أما الآن وقد وسع الله في رزقي، ومنذ فترة توفي خالي إلى رحمة الله، فما العمل؟ وكيف أسدد؟ هل أسدد ما علي من مال لورثة خالي، أم كيف أفعل؟ جزاكم الله خيرًا.","title":"حكم من عليه دين لرجل توفي","answer":"الجواب:  نعم، الواجب عليك أن تدفع الذي في ذمتك لخالك للورثة، وتخبرهم بذلك، فإذا كان لهم مسؤول ووكيل؛ تعطيه الوكيل، أو المحكمة حتى توزعه بينهم، وإذا كانوا محصورين، وأمكنك أن توزعه بينهم؛ كفى.  المقصود: أنه يسلم للورثة إما بأنفسهم، وإما بواسطة الوكيل، وكيلهم أو بواسطة المحكمة.","link":"https://binbaz.org.sa/fatwas/10905/حكم-من-عليه-دين-لرجل-توفي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41805.mp3","categories":["السلف والقرض"]},{"id":12966,"question":"تقول هذه السائلة: هل ما يسمى بالجمعية، والتي يدفع كل فرد منها مبلغًا يقبضه الآخر مرة واحدة، وهكذا يدور على كل واحد في الجمعية، هل فيه ربا؟","title":"حكم الجمعيات التي تقام بين الموظفين وغيرهم","answer":"الجواب: الصواب: لا بأس به، قد صدر قرار من مجلس هيئة كبار العلماء بأنه لا حرج في ذلك، إذا اتفقوا على قرض بينهم، كل واحد يأخذ ألفين إذا جاءه الدور، أو كل واحد يأخذ ثلاثة، أو عشرة، لا بأس، سواء الرجال، أو النساء؛ لأنه قرض ما فيه زيادة، ما فيه تفاضل، بل المثل بالمثل نعم.","link":"https://binbaz.org.sa/fatwas/11183/حكم-الجمعيات-التي-تقام-بين-الموظفين-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50301.mp3","categories":["السلف والقرض"]},{"id":13077,"question":"هذا سؤال من إحدى المستمعات تقول: عندي مشكلة وهي: أنني ذات يوم خدعني إبليس، وذلك بأن جعلني أخدع صاحب السوق عندما أخذت منه حاجتي، وقلت له: سوف أعطيك الثمن بعدين، ومرت سنة أو أكثر وأنا على هذا الحال، وعندما أردت أن أعطيه فجأة تغير المكان، وصار سوقًا آخر، ولم يوجد صاحب هذا الدين الذي بذمتي، وسؤالي رغم أنني نادم جدًا لم أجده، ولم أعرف أحدًا يعرفني عليه؛ لكي أعطيه المبلغ، وسألت أكثر من واحد وقالوا: ليس موجود. فماذا أفعل؟","title":"كيف يفعل من عنده دين لشخص جهل مكانه وعنوانه؟","answer":"الجواب:  عليك التوبة أولًا إلى الله، عليك التوبة والندم والعزم الصادق ألا تعود لمثل هذا؛ لأنك ظلمته، وتعديت عليه، وعليك الصدقة بهذا .. تصدق بهذا المال على الفقراء بالنية عن صاحبه، إذا لم تستطع معرفة عنوانه، وإيصال المال إليه، إذا عجزت؛ فعليك أن تتصدق به على الفقراء بالنية عن صاحبه، وتدعو له، ويكفي -والحمد لله- مع التوبة والندم مما فعلت. نعم.","link":"https://binbaz.org.sa/fatwas/11294/كيف-يفعل-من-عنده-دين-لشخص-جهل-مكانه-وعنوانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50709.mp3","categories":["السلف والقرض"]},{"id":13095,"question":"السائل الذي رمز لاسمه بـ(خ. م. ح) أرسل بهذه الرسالة، يقول: بأنه شاب اقترض من بنك التسليف مبلغًا، وهو مبلغ خمسة عشر ألف ريال، وهو ما يسمى بقرض زواج، وذلك القرض لابد له من شروط، وهي أن يكون الشخص المقترض متسببًا، وإذا كان موظفًا؛ فلابد أن يكون الراتب ثلاثة آلاف ريال فأقل.. يقول: علمًا بأنني أخذت من هذا البنك هذا القرض، وراتبي أكثر من ثلاثة آلاف، واستلمت هذا القرض بناء على أنني متسبب، وأنا موظف، ويتم سداد هذا القرض شهريًا بلا زيادة، ولا نقصان، واقتراضي هذا بسبب بعض الديون التي كانت علي، فماذا أفعل -يا سماحة الشيخ- الآن، وبماذا تنصحونني؟ علمًا بأن حالتي المادية لا تسمح لي بإرجاع المبلغ، وجزاكم الله خيرًا.","title":"كيفية التخلص من سداد دين من بنك لغرض الزواج","answer":"الجواب:  الواجب عليك التوبة إلى الله من عدم بيان الحقيقة عند القرض، الواجب عليك التوبة إلى الله، والاستغفار من عدم بيان الحقيقة، وعليك أن توفي القرض حسب التعليمات المتبعة، عليك أن توفي هذا القرض حسب التعليمات المتبعة عند البنك، وعليك أن تجتهد في ذلك، سواء كنت متسببًا، أو موظفًا عليك أن تسدد حسب الطاقة، وحسب التعليمات المتبعة، وإذا كنت لا تستطيع بيِّن للبنك، والبنك ينظر في الأمر حسب ما عنده من التعليمات، نسأل الله للجميع التوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11311/كيفية-التخلص-من-سداد-دين-من-بنك-لغرض-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50805.mp3","categories":["السلف والقرض"]},{"id":13757,"question":"من الرياض السائل: (أ. أ) يقول: هل يجوز إسقاط الدين، واحتسابه من الزكاة؟","title":"حكم إسقاط الدين واحتسابه من الزكاة","answer":"الجواب: لا، ليس له إسقاطه واحتسابه من الزكاة، ولكن ينظر المعسر، ينظره، وإذا أعطاه من الزكاة لأجل عسره، وفقره؛ لا بأس، أما إسقاطه الدين عن الزكاة، لا، الزكاة إعطاء، ليست إسقاطًا، فلا يقي ماله بإسقاط الدين عن المعسرين، ولكن يجب عليه أن يمهلهم، وإذا أسقطهم تبرعًا ومساعدة، لا زكاةً؛ فلا بأس. المقدم: إذا اشترط عليه -سماحة الشيخ- أن يعطيه من الزكاة بشرط أن يسدد الدين الذي عليه؟ الشيخ: ما يصلح.  المقدم: ما يصلح.  الشيخ: لا، يعطيه ولا يشترط، يعطيه من الزكاة لفقره، وإن أعطاه، ردها إليه من دون شرط، أوفاه مما أعطاه؛ فلا بأس، أما يقول: أعطيك تعطيني، لا، ما يصح، هذا كالإسقاط. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12133/حكم-اسقاط-الدين-واحتسابه-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53526.mp3","categories":["السلف والقرض","إخراج الزكاة وأهلها"]},{"id":13762,"question":"من الرياض السائل: (أ. أ) يقول: هل يجوز إسقاط الدين، واحتسابه من الزكاة؟","title":"حكم إسقاط الدين واحتسابه من الزكاة","answer":"الجواب: لا، ليس له إسقاطه واحتسابه من الزكاة، ولكن ينظر المعسر، ينظره، وإذا أعطاه من الزكاة لأجل عسره، وفقره؛ لا بأس، أما إسقاطه الدين عن الزكاة، لا، الزكاة إعطاء، ليست إسقاطًا، فلا يقي ماله بإسقاط الدين عن المعسرين، ولكن يجب عليه أن يمهلهم، وإذا أسقطهم تبرعًا ومساعدة، لا زكاةً؛ فلا بأس. المقدم: إذا اشترط عليه -سماحة الشيخ- أن يعطيه من الزكاة بشرط أن يسدد الدين الذي عليه؟ الشيخ: ما يصلح.  المقدم: ما يصلح.  الشيخ: لا، يعطيه ولا يشترط، يعطيه من الزكاة لفقره، وإن أعطاه، ردها إليه من دون شرط، أوفاه مما أعطاه؛ فلا بأس، أما يقول: أعطيك تعطيني، لا، ما يصح، هذا كالإسقاط. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12133/حكم-اسقاط-الدين-واحتسابه-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53526.mp3","categories":["السلف والقرض","إخراج الزكاة وأهلها"]},{"id":14050,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الدمام، باعثة الرسالة إحدى الأخوات من هناك تقول: المرسلة أم أحمد الحافي ، أم أحمد لها أربعة أسئلة شيخ عبد العزيز .تسأل في سؤالها الأول وتقول: هل قرض البنك العقاري والزراعي يعتبر دين على الشخص إذا استقرضه وتوفي قبل أن يسدده؟ ثم ماذا يجب على الورثة تجاه ذلك؛ لأنهم يريدون في الواقع راحة الميت، إذا لم يستطيعوا أن يسددوا البنك بسرعة فما الحكم؟","title":"كيفية تسديد الديون التي على الميت للبنوك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالقرض الذي للبنك العقاري، ولغيره من البنوك الزراعية ونحوها، مثل غيره من الديون، يجب أن يسدد في وقته في حق الحي والميت، وإذا مات الإنسان وعليه دين للبنك؛ وجب أن يسدد من التركة في أوقاته إذا التزم به الورثة، فإن لم يلتزموا سدد في الحال من التركة؛ حتى يستريح الميت من تبعة الدين، وقد جاء في الحديث عنه عليه الصلاة والسلام أنه قال: نفس المؤمن معلقة بدينه حتى يقضى عنه.\nلكن إذا كان الدين مؤجلًا والتزم الورثة -أو بعضهم- بأنه يؤدى في وقته؛ فإنه يتأجل، ولا يضر الميت؛ لأنه مؤجل، فإن لم يلتزم أحد به في وقته؛ وجب أن يسدد من التركة، حتى يسلم الميت من تبعة ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، شيخ عبد العزيز إذا كانت هذه القروض على شكل أقساط، فما هو توجيهكم؟\nالشيخ: مثلما تقدم، كل قسط في وقته.\nالمقدم: كل قسط في وقته.\nالشيخ: يسدد في وقته، إلا إذا لم يوجد من الورثة من يلتزم بذلك؛ فإنه يسدد الجميع من نفس التركة. نعم، كالدين الحال.\nالمقدم: كالدين الحال تمامًا، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12474/كيفية-تسديد-الديون-التي-على-الميت-للبنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60801.mp3","categories":["السلف والقرض"]},{"id":14126,"question":"هذه رسالة بعث بها المستمع رزق الله سلمان من المملكة الأردنية الهاشمية، الأخ رزق الله يسأل ويقول: اقترض رجل مبلغ مائة ريال من أحد أصدقائه على أن يعطيه في موسم الحصاد بدلًا منها عشرين صاعًا قمحًا، مع العلم أن العشرين صاعًا تساوي مائة وخمسين ريالًا، فهل هذه الزيادة مشروعة؟ وإن كانت مشروعة فإن فيها زيادة ليست مقابل شيء إلا مقابل التأجيل، أرجو توضيح هذه المسألة. جزاكم الله خيرًا.","title":"حكم إعطاء شخص مبلغًا على أن يعيده آصاعًا معلومة","answer":"الجواب: إذا كان ذلك على سبيل السلم، فلا بأس أن يعطيه مائة ريال في عشرين صاع يسلمها له في رمضان في شوال، هذا يسمى السلم، والنبي ﷺ قال لما قدم المدينة وهم يسلفون في الثمار السنة والسنتين قال: من أسلف في شيء فليسلف في كيل معلوم ووزن معلوم إلى أجل معلوم، فإذا أعطاه مائة ريال في عشرين صاعًا، أو أعطاه ألف ريال في مائة صاع أو أكثر إلى أجل معلوم من الذرة أو من الحنطة أو من الأرز فلا بأس، هذا يسمى السلم ما يسمى قرض، أما إذا أعطاه مائة ريال قرضًا وقال: شرط أنك تعطيني عنها عشرين صاعًا وقت كذا ووقت كذا، فهذا معناه السلم، لكن سوء تعبير، تسمى سوء تعبير ما هي بقرض. أما إذا أعطاه قرضًا على أنه يعطيه أكثر من مائة في الأجل المعلوم يعطيه مائة وعشرين ريال، مائة وثلاثين ... يزيده هذا ربا ما يصح، لكن بعض الناس قد لا يحسن عبارة السلم، فإذا أعطاه مائة ريال قال: هذه مائة ريال تقضي بها حاجتك الآن، وتعطيني مقابلها في شهر كذا عشرين صاعًا، ثلاثين صاعًا من الأرز من الحنطة من الذرة، هذا يسمى السلم أو تمر كذلك، إذا صار أجل معلوم والمطلوب معلوم أصواعًا معلومة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12565/حكم-اعطاء-شخص-مبلغا-على-ان-يعيده-اصاعا-معلومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48421.mp3","categories":["السلف والقرض","البيوع"]},{"id":14311,"question":"لي أخ توفي قبل اثنتي عشرة سنة، وقبل وفاته بعدة سنوات أخذ من أحد الأشخاص خمسين ريالًا بدون علم هذا الشخص، واليوم مضى عليها أكثر من خمس عشرة سنة، هل أنا أذهب إلى الشخص وأعطيه الفلوس أم أتصدق بها على الفقراء؟ أفيدوني جزاكم الله خيرًا.","title":"ما يلزم من مات له قريب وفي ذمته مال؟","answer":"الجواب: الواجب عليك رد الفلوس إلى صاحبها، رد النقود إلى صاحبها بأي طريقة توصلها إليه، وإذا كنت لا تحب أن يعلم ذلك توصلها إليه بطرق أخرى لا يعلم منها أنها منك ولكن مع التيقن أنها وصلت إليه، كأن يقول له الرسول: هذه أعطانيها لك إنسان يقول: إن عليه لك حق، فيعطيه إياه وتبرأ ذمته، وليس لك ترك ذلك بل عليك أن تسلمها له مادمت تستطيع تسليمها له، فإن عجزت عن تسليمها له لكونه غائبًا لا تعرف محله، أو لكونه مات ولا تعرف ورثته فإنك تتصدق بها على الفقراء بالنية عنه مع التوبة والندم والإقلاع والعزم أن لا تعود في مثل ذلك والله يعفو عن التائب .\nأما مع القدرة على إيصالها إليه أو ورثته إن كان ميتًا، فالواجب عليه إيصالها إليه بأي طريق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12796/ما-يلزم-من-مات-له-قريب-وفي-ذمته-مال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62208.mp3","categories":["السلف والقرض"]},{"id":14314,"question":"لي أخ توفي قبل اثنتي عشرة سنة، وقبل وفاته بعدة سنوات أخذ من أحد الأشخاص خمسين ريالًا بدون علم هذا الشخص، واليوم مضى عليها أكثر من خمس عشرة سنة، هل أنا أذهب إلى الشخص وأعطيه الفلوس أم أتصدق بها على الفقراء؟ أفيدوني جزاكم الله خيرًا.","title":"ما يلزم من مات له قريب وفي ذمته مال؟","answer":"الجواب: الواجب عليك رد الفلوس إلى صاحبها، رد النقود إلى صاحبها بأي طريقة توصلها إليه، وإذا كنت لا تحب أن يعلم ذلك توصلها إليه بطرق أخرى لا يعلم منها أنها منك ولكن مع التيقن أنها وصلت إليه، كأن يقول له الرسول: هذه أعطانيها لك إنسان يقول: إن عليه لك حق، فيعطيه إياه وتبرأ ذمته، وليس لك ترك ذلك بل عليك أن تسلمها له مادمت تستطيع تسليمها له، فإن عجزت عن تسليمها له لكونه غائبًا لا تعرف محله، أو لكونه مات ولا تعرف ورثته فإنك تتصدق بها على الفقراء بالنية عنه مع التوبة والندم والإقلاع والعزم أن لا تعود في مثل ذلك والله يعفو عن التائب .\nأما مع القدرة على إيصالها إليه أو ورثته إن كان ميتًا، فالواجب عليه إيصالها إليه بأي طريق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12796/ما-يلزم-من-مات-له-قريب-وفي-ذمته-مال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62208.mp3","categories":["السلف والقرض"]},{"id":14641,"question":"رسالة مطولة، بعث بها أحد الإخوة المستمعين، وقع في نهايتها بقوله: المليجي من جدة، أخونا رسالته كالتالي، يقول: والدي دخل شريك مع أحد الأشخاص، على الشخص رأس المال، وعلى والدي أن يدير المحل، وكنت أنا الذي أدير المحل، والدي للأسف الشديد كان يأخذ مالًا من محل الشراكة، ويدخله في محله الخاص به، وكنت لا أقبل هذا الفعل من والدي، ولكن كنت لا أستطيع أن أعمل شيئًا، وهذا والدي.المهم استمر هذا الوضع إلى أن حان وقت الجرد، وانتهت الشراكة، وحصل طبعًا خلط في مال والدي؛ لأنه أدخل مال الشراكة في ماله الخاص، وهذا أنا أعرفه خطأ، وبعد ذلك ذهب والدي وحج من ماله المخلوط، الآن والدي توفي -يرحمه الله-، والشريك توفي -يرحمه الله-، و هل علي أنا شيء؛ لأني كنت أسمح لوالدي أن يأخذ من مال الشراكة؟وإذا كان علي شيء أنا هل من الممكن أن آخذ العفو والسماح من أبناء الشريك؛ لأنه قد توفي كما أسلفت ولوالدي، أرجو أن تفيدوني حول هذه القضية؟جزاكم الله خيرًا.","title":"ما يلزم من توفي والده وفي ذمته حقوق للآخرين؟","answer":"الجواب: الواجب عليك السعي في تخليص ذمة والدك، إما بأن تدفع له ما تعتقده أنه حق لهم لأولاد الشريك، وإما أن تستسمحهم إذا كانوا مرشدين، فإذا سمحوا عن والدك، وعفوا عما أخذ من مالهم فلا حرج.  أما إن كانوا غير مرشدين، بل قاصرون، فإنك تعطيهم حقهم الذي تعتقد أن أباك استأخذه من مال الشركة، تخرجه من التركة، وتعطيهم إياه، وإذا كان معك شركاء في التركة تخبرهم بما جرى حتى يوافقوك على ما يبرئ الذمة لوالدك، فإن أبوا هذا إلى المحكمة، ترفع الأمر إلى المحكمة، والمحكمة تأمركم بما ترى في ذلك.  أما إن وافق الشركاء معك، يعني: الورثة معك من أبيك إذا وافقوا على أنك تدفع لأولاد الشريك ما دخل على أبيك فالحمد لله، أو عفا ورثة الشريك -عفوًا- عما دخل على أبيك فالموضوع يعتبر منتهيًا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13136/ما-يلزم-من-توفي-والده-وفي-ذمته-حقوق-للاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62706.mp3","categories":["السلف والقرض"]},{"id":14652,"question":"أبو معاذ، من حائل، يقول: صديق لي أنهى خدمته من العمل، واستحق مكافأة نهاية الخدمة، وكان يريد السفر خروج نهائي، وقد صرفت له تذاكر له ولزوجته، وأنهى الستة شهور في سكنه، وطلب مني أن أعطيه المبلغ، ويكتب لي وكالة شرعية بالمبلغ الذي له؛ لأن صرف هذا المبلغ يحتاج إلى شهرين على الأقل، وإن بقي فسوف يدفع أجرة المبيت، ويفقد تذاكر السفر، فأعطيته المبلغ كاملًا، وكتب لي وكالة شرعية بذلك المبلغ كاملًا، وقبل سفره قدم لي هدية، وأنا لا أعلم شيئًا عن هذه الهدية من حيث النوع، ومن حيث الثمن فأخذتها، فهل علي إثم في ذلك؟","title":"حكم أخذ الهدية ممن عنده دين","answer":"الجواب: ليس عليك شيء، ما دام ما فيه شرط، إنما هو من نفسه لا شيء؛ لأنك أحسنت إليه، والله -جل وعلا- يحب من عباده أن يكافؤوا بالإحسان، مثلما قال ﷺ: من صنع إليكم معروفًا فكافؤوه فإذا أحسن إليك إنسان، وأعطيته مكافأة فلا بأس، النبي ﷺ كان يقترض ويكافئ. الممنوع الشرط، تقول له: ما أسلفك إلا تعطيني زيادة، هذا ما يجوز، أما أقرضته وأحسنت إليه ثم أعطاك هدية لا حرج عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13139/حكم-اخذ-الهدية-ممن-عنده-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55918.mp3","categories":["السلف والقرض"]},{"id":14837,"question":"المستمع عبدالله الحماد، يقول: سعودي مقيم في دولة قطر، بعث برسالة ضمنها هذا السؤال، يقول: لي أخ توفي منذ ثنتي عشرة سنة، وقبل وفاته بسنوات قليلة أخذ من أحد الأقارب مبلغ خمسين ريالًا بدون علم منه، كان عمر أخي آنذاك سبع عشرة سنة، ماذا أفعل أنا حتى يعفو عنه الشخص الذي ذكرت؟جزاكم الله خيرًا.الشيخ: أعد أعد.المقدم: يقول: لي أخ توفي منذ ثنتي عشرة سنة، وقبل وفاته بسنوات قليلة أخذ من أحد الأقارب خمسين ريالًا، بدون علم من ذلك الشخص، كان عمر أخي آنذاك سبع عشرة سنة، ماذا أفعل أنا حتى يعفو عنه ذلك الشخص؟","title":"حكم من أخذ مالًا دون علم صاحبه ثم مات","answer":"الجواب: الواجب تسليم الخمسين إلى صاحبها، حتى يعفو عنه، ويسمح عنه، فإن سمح بدون تسليم الدراهم، وعفا عن الميت فلا بأس جزاه الله خيرًا، وهذا في التركة إذا كان له تركة.  أما إذا كان ليس لأخيك تركة، وتبرعت أنت بها من مالك فجزاك الله خيرًا، وإن سمح صاحبها، وعفا عن أخيك كفى ذلك، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13324/حكم-من-اخذ-مالا-دون-علم-صاحبه-ثم-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63816.mp3","categories":["السلف والقرض"]},{"id":14920,"question":"رسالة طويلة جدًا، باعثها مستمع من الموصل في الجمهورية العراقية، منطقة السادة، حي الوحدة، ملخص ما في هذه الرسالة: أن في ذمته مبلغ خمسين دينارًا لرجل مسيحي متوفى، لمن يدفع هذا المبلغ؟","title":"حكم من عليه دين لمسيحى متوفى","answer":"الجواب: عليه أن يدفعها للورثة، إذا كان له ورثة، إذا كان يعرف ورثته؛ عليه أن يدفع ذلك إليهم، وعليه أن يسأل عنهم، فإن لم يجد، ولم يعرف له ورثة؛ فإنه يتصدق به عنه؛ لأنه ينفعه، يعطيه بعض الفقراء بالنية عن صاحب المال؛ لعل الله يخفف عنه بذلك شيئًا من عذابه. المقصود: أنه يتصدق به عن ذلك الميت الذي هو صاحب الحق، والله -جل وعلا- لا يضيع أجر من أحسن عملًا ، وإن كان كافرًا؛ قد يخفف عنه. المقدم: قد يخفف عنه. الشيخ: نعم لذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13414/حكم-من-عليه-دين-لمسيحى-متوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64004.mp3","categories":["السلف والقرض"]},{"id":15443,"question":"هل هناك فرق بين الدين والقرض يا سماحة الشيخ؟","title":"الفرق بين القرض والدين","answer":"الجواب: القرض من الدين، الدين يعم، ثمن المبيع إذا كان مؤجل دين، والقرض دين، قيمة المتلفات إذا كان في الذمة دين، والأجرة إذا كان في الذمة دين، وهكذا فالقرض من الدين.","link":"https://binbaz.org.sa/fatwas/13955/الفرق-بين-القرض-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56805.mp3","categories":["السلف والقرض"]},{"id":15890,"question":"يسأل سؤالًا آخر، فيقول فيه: أيهما أكثر ثوابًا الصدقة أم ثواب القرض؟","title":"أفضلية الصدقة على القرض","answer":"الجواب: الصدقة مطلوبة، وينبغي للمؤمن أن يجتهد فيها، ويحرص على مساعدة المحاويج، وهي أفضل من القرض، ينبغي للمؤمن أن يحرص على الصدقة لأنها تمليك للفقير؛ ليتصرف كيف شاء، أما القرض فيرد بدله، لكن القرض مشروع، وفيه فضل، وفيه إحسان ومساعدة للمسلم، وتفريج كربة وتيسير، والنبي ﷺ اقترض -عليه الصلاة والسلام- قال: إن خيار الناس أحسنهم قضاءً فالصدقة أفضل وأعظم نفعًا، والقرض مفيد ونافع، ونوع من الصدقة، نعم.","link":"https://binbaz.org.sa/fatwas/14483/افضلية-الصدقة-على-القرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74510.mp3","categories":["السلف والقرض"]},{"id":16855,"question":"من المنطقة الشرقية رسالة بعثت بها إحدى الأخوات المستمعات، تقول: ( أم محمد. ع. ق) من بقيق، أختنا لها عدة قضايا، في إحداها تقول: شخص مات، وعليه دين لإحدى المؤسسات تسديد فواتير، وسوف يسدد هذا الدين على أقساط شهرية، تصل السنة، أو أقل، أو أكثر مثلًا، حسب اتفاق تم بين الورثة، وبين المؤسسة، هل ذمة الميت تكون معلقة حتى ينتهي من تسديد جميع الدين، أو تبرأ من حين يبدأ في التسديد، ما هي وجهة نظركم في ذلك؟ وما الحل الذي ترونه مناسبًا حتى تبرأ ذمة الميت؟ علمًا بأن هذه المبالغ تراكمت لدى المؤسسة؛ لأنه كان في تلك الفترة مريضًا بالمستشفى، وجهونا جزاكم الله خيرًا.","title":"حكم من مات وعليه دين على أقساط","answer":"الجواب: إذا كان الدين حالًا، وفي التركة سعة للقضاء؛ وجب القضاء، وجبت المبادرة بقضاء الديون كلها، من دون تأخير، أما إن كانت الديون مؤجلة؛ تبقى على آجالها، ولا حرج على الميت في ذلك، أو كانت التركة عاجزة، ليس فيها ما يوفي بالديون، وإنما الموفون الورثة؛ فلا بأس أن يؤجلوا، وهم محسنون، لكن إذا كانت التركة فيها سعة، فالواجب أن توفى الديون بسرعة؛ لقوله ﷺ: نفس المؤمن معلقة بدينه حتى يقضى عنه. فالواجب البدار بقضاء الديون من التركة، وعدم التأجيل، وعدم التأخير إلا إذا كانت الديون مؤجلة، فهي تبقى على آجالها إلا أن يسمح الورثة بتعجيلها. وهكذا يكون الدين من البنك العقاري يبقى مؤجلًا على حاله، على أقساطه، لكن إذا كان الميت ليس خلفه شيء؛ فإن الورثة محسنون، فإذا عجلوا القضاء، أو أجلوه؛ فلا حرج عليهم، هم محسنون بكل حال. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15595/حكم-من-مات-وعليه-دين-على-اقساط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71904.mp3","categories":["السلف والقرض"]},{"id":17000,"question":"بعد هذا رسالة وصلت إلى البرنامج من مكة المكرمة باعثها مستمع من هناك يقول: أخوكم في الله (ج. ح. س) أخونا يسأل سماحتكم فيقول: ما هو الحكم في التعامل في الجمعيات بين عدد من الزملاء في العمل، مثال ذلك: أن يتفق خمسة من الأشخاص على عمل جمعية تعاونية بمبلغ ألفين ريال، ويتم تسليم المبلغ وهو ثمانية آلاف ريال مثلًا للأول حسب الترتيب المتفق عليه، ويتم تسليم الثاني نفس المبلغ حتى نهاية الخمسة الأشهر، أرجو إفتاءنا في هذا الموضوع، وهل يدخل هذا في باب القرض بمنفعة؟ جزاكم الله خيرًا.","title":"حكم ما يُسمى بالجمعيات التعاونية","answer":"الجواب: إذا كان القرض من دون زيادة، بل يتفقون على قرض معلوم بينهم، كل شهر لواحد ألفان، أو ألف، أو أقل، أو أكثر فلا بأس بهذا، قد صدر قرار مجلس هيئة كبار العلماء بالجواز في ذلك إذا كان من دون زيادة، نعم. المقدم: جزاكم الله خيرًا، يسأل: هل هو من القرض بمنفعة، أو لا؟ الشيخ: ليس من ذلك؛ لأنهم مستوون، ليس فيه شرط لأحد على أحد، وليس فيه فائدة لأحد على أحد، نعم. المقدم: جزاكم الله خيرًا، الموضوع سماحة الشيخ أنه إذا أراد شخص أن يسهم معهم، لكن دون أن يدفع مبلغًا ليقرضوه، لا يفعلوا ذلك، فما هو توجيهكم. الشيخ: إذا أحبوا أن يقرضوه بدون شيء، معروف منهم جزاهم الله خيرًا، بدون شيء بدون ....  المقدم: لا يقرضونه إلا أن يكون مساهمًا معهم. الشيخ: ما في بأس، هذا شرط بينهم، لا حرج، لا يقرضون إلا من ساهم معهم. المقدم: نعم. الشيخ: لا بأس. المقدم: ليس هذا من النفع المذكور ... الشيخ: لا لا ما يضر؛ لأن هذا نفع ما فيه زيادة، ما فيه مقابل، كلهم سواء فيه. المقدم: كلهم سواء، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15774/حكم-ما-يسمى-بالجمعيات-التعاونية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72006.mp3","categories":["السلف والقرض"]},{"id":17110,"question":"من أسئلة السائل من كينيا يقول: يا سماحة الشيخ! حفظكم الله، إذا مات المسلم، أو الكافر، وعلى أحدهما دين للآخر، فكيف يتقاضيان بينهما يوم القيامة؟","title":"حكم المسلم إذا مات وعليه دين لكافر والعكس","answer":"الجواب: على الورثة أن يؤدوا الدين، فإذا لم يؤدوا عنه أمرهم إلى الله يوم القيامة، هذا إلى الله -جل وعلا- لكن يقول ﷺ : من أخذ أموال الناس يريد أداءها أدى الله عنه، ومن أخذها يريد إتلافها أتلفه الله فأمرهم إلى الله -جل وعلا- لكن إذا كان خلفه تركة يلزم الورثة أن يؤدوا عنه الدين. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15916/حكم-المسلم-اذا-مات-وعليه-دين-لكافر-والعكس","audio":"","categories":["السلف والقرض"]},{"id":17248,"question":"هذا السائل أبو عبدالله يقول: حديث: نفس المؤمن معلقة بدينه حتى يقضى عنه إذا مات المسلم، وعليه دين، فهل يقضي عنه الأبناء؟ وإذا لم يكن له تركة فما العمل مأجورين؟","title":"حكم قضاء الدين عن الميت","answer":"الجواب: الواجب أنه يقضي عنه الأبناء أو غير الأبناء، يعني: الورثة إذا كان له تركة، يجب عليهم أن يقضوا من التركة هذا الدين، ولا يجوز لهم التساهل في هذا، أما إذا كان ما خلف تركة ما وراه شيء؛ فلا يلزمهم شيء، لكن إن قضوا عنه من باب التبرع فهم مأجورون، وإلا فلا يلزمهم إذا كان ما خلف تركة، أما إذا كان خلف تركة؛ لابد من القضاء، كان عقارًا يباع العقار، ويوفى الدين، وإن كان نقودًا يوفون الدين من النقود، وليس لهم التساهل في هذا، بل يجب عليهم أن يبادروا بذلك. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16080/حكم-قضاء-الدين-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59202.mp3","categories":["مسائل متفرقة في الجنائز","السلف والقرض"]},{"id":17343,"question":"هل يجوز أن يستدين المسلم لأجل شراء الكتب الشرعية للاطلاع، والتعلم، والتفقه في الدين، وهل يجب عليه بيع هذه الكتب في حالة عدم استطاعته الوفاء بالدين الذي عليه؟","title":"ما حكم الاستدانة من أجل شراء الكتب الشرعية؟","answer":"الجواب: إذا كان له أسباب، وله كسب يستطيع الوفاء منه، لا بأس يستدين، إذا كان عنده يعني وفاء، عنده أسباب يوفي منها، أما إذا كان لا، ليس عنده شيء؛ فلا يستدين؛ لأن استدانته ضياع لحق الناس، فلا يستدين، بل يتصل بالمكتبات، ويطالع في المكتبات التي فيها الكتب، ويستعير من إخوانه .... وينتفع بذلك، ولا حاجة إلى الاستدانة، وإذا استدان، وغلط واستدان، وما عنده وفاء يبعها، ويوفي، يبيعها ..... ويوفي أهل الدين، ولا يتساهل في حق المسلم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16180/ما-حكم-الاستدانة-من-اجل-شراء-الكتب-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72412.mp3","categories":["السلف والقرض"]},{"id":17487,"question":"السائل رمضان من سوريا يقول: هل يجوز مبادلة حنطة بحنطة على سبيل الاستقراض علمًا بأن الوزن معلوم؟","title":"حكم مبادلة حنطة بحنطة","answer":"الجواب: إذا كان ...... قرض يرد مثلما أخذ، إذا استقرض مائة صاع أو مائة كيلو من الحنطة يرد مثلها، وإن رد أزيد من دون شرط فلا بأس: إن خيار الناس أحسنهم قضاء، أما أن يأخذ القرض بزيادة فلا يجوز هذا ربا، كونه يأخذ مائة صاع حنطة بمائة وعشرة صاع حنطة، أو مائة صاع رز بمائة وعشرة رز ما يجوز، أما إذا أخذ قرضًا اقترض من أخيه مائة صاع رز أو حنطة، ثم رد مثل ذلك لا حرج، فالحمد لله، وإن رد أزيد من دون شرط بل مجرد تبرع وإحسان فلا بأس لقوله ﷺ: إن خيار الناس أحسنهم قضاء، وكان ﷺ ربما اقترض ورد أكثر عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/16399/حكم-مبادلة-حنطة-بحنطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77319.mp3","categories":["السلف والقرض"]},{"id":17699,"question":"من أسئلة السائل يقول: دار نقاش حول الجمعية التي تفعل في كثير من بعض الإخوة هل هي جائزة أم محرمة نرجو البيان والتوضيح في ذلك يا شيخ؟","title":"حكم ما يسمى بالجمعيات التي تكون كل شهر لعضو","answer":"الجواب: إن كان المراد بالجمعية القرض اللي بينهم كهذا يأخذ ألف ومن هذا ألف ومن هذا ألف ثم يقضيهم والآخر كذلك والآخر كذلك فلا بأس، هذا قرض لا حرج فيه. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16650/حكم-ما-يسمى-بالجمعيات-التي-تكون-كل-شهر-لعضو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77610.mp3","categories":["السلف والقرض"]},{"id":17896,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع علي الهاجري أخونا علي يقول في رسالته: أفيدكم يا سماحة الشيخ بأنني مديون لعدد من الأشخاص بعضهم من مدة طويلة وبعضهم مدته ليست بطويلة، ولم أكن أجد المال أثناء مطالبتهم لي في ذلك الوقت والآن وجدت المال ولكن بعضهم موجود والبعض الآخر غير موجود، ماذا أفعل بأموال غير الموجودين إذا لم أجدهم؟ جزاكم الله خيرًا.","title":"كيفية قضاء الدين إذا لم يعرف مكان صاحبه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفعليك أن تسأل عن أماكنهم ومتى عرفت عناوينهم ترسل لهم حقوقهم وهذا يجب عليك؛ لأن أداء الدين واجب وهذا من وسائل أدائه، فعليك أن تسأل وتحرص حتى تعرف أماكنهم وعناوينهم ثم ترسل لهم حقوقهم ولا تعجل فلعلهم يقدمون ولعلك تعرف عناوينهم إن لم يقدموا لا تعجل، فإن أيست من ذلك فتصدق بها عنهم بالنية عن أصحابها، ومتى حضروا تخيرهم فإن قبلوا الصدقة فالأجر لهم، وإن لم يقبلوها صار الأجر لك وتعطيهم حقهم، نسأل الله أن يوفق الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16910/كيفية-قضاء-الدين-اذا-لم-يعرف-مكان-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84601.mp3","categories":["السلف والقرض"]},{"id":17965,"question":"يقول في سؤال آخر: أنا صاحب دكان، وقد سبق لي أن أقرضت أحد الأشخاص مالًا وكلما طلبت المبلغ يقول: لا أملك شيئًا، فهل يجوز لي أن أخصم ما عليه من مال الزكاة؟","title":"ما حكم جعل القرض زكاة؟","answer":"الجواب: لا. ليس لك أن تخصم ما عليه من مال الزكاة؛ لأن الزكاة دفع إيتاء للفقراء، ولكن تمهله حتى يوفي الله عنه؛ لأن الله يقول سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، فعليك أن تنظر أخاك، يقول النبي ﷺ: من أنظر معسرًا أو وضع له أظله الله في ظله يوم لا ظل إلا ظله. فأنت بين أمرين: إما أن تنظره، وإما أن تبرئه من المال وتسامحه، وأما أن تسقطه من الزكاة فلا، لكن إذا أعطيته من الزكاة لفقره وأعاد ذلك إليك عن الدين من دون شرط بينك وبينه ولا تواطؤ فلا حرج، يعني: لو أعطيته من الزكاة ولكن هو رد إليك ذلك المال من الدين أو بعضه من الدين من دون تواطؤ بينكم ولا حيلة ولا شرط فلا بأس بهذا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16996/ما-حكم-جعل-القرض-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84805.mp3","categories":["السلف والقرض","إخراج الزكاة وأهلها"]},{"id":18790,"question":"اقترضت من صديق مبلغًا من المال بالدولار، هل يجوز سداد هذا المبلغ بما يساويه من عملة أخرى كالريال اليمني مثلًا، أو الجنيه؟","title":"حكم قضاء الدين بعملة غير التي استدان بها","answer":"الجواب: نعم لا بأس أن يكون الإنسان اقترض عملة، ثم يسددها بعملة أخرى بالتراضي، إذا رضي صاحب العملة الأولى أن يأخذ عنها عملة أخرى فلا حرج في ذلك، يدًا بيد من غير تأخير، فقد ثبت عن رسول الله ﷺ أنه قيل له: يا رسول الله! إنا نبيع بالدراهم ونأخذ الدنانير، ونبيع بالدنانير ونأخذ الدراهم؟ فقال -عليه الصلاة والسلام-: لا بأس أن تأخذها بسعر يومها ما لم تفترقا وبينكما شيء.  فإذا اقترضت مثلًا مائة دولار، وأعطيت صاحبها عنها عملة أخرى، كالريال السعودي أو اليمني، أو الدينار الأردني أو العراقي؛ يدًا بيد، بحسب القيمة، فلا بأس بذلك، أو زدته زيادة على ذلك؛ لأنك تراه محسنًا إليك، زدته على ذلك، فلا بأس؛ لقوله ﷺ: إن خيار الناس أحسنهم قضاء . وهكذا لو باع عليك سيارة بعشرة آلاف -مثلًا- دولار، ثم أعطيته عنها ما يقابلها من دنانير أو الريال السعودي أو اليمني، أو ما أشبه ذلك من العمل الأخرى؛ فلا بأس، لكن بشرط التقابض في المجلس، وأن لا تتفرقا وبينكما شيء، وأن تعطيه إياها بسعر يومها، حين المعاوضة، نعم.","link":"https://binbaz.org.sa/fatwas/17919/حكم-قضاء-الدين-بعملة-غير-التي-استدان-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87602.mp3","categories":["السلف والقرض"]}]
